/* Dehesa Index — Metodología (4 idiomas). Todo lo que afirma esta página describe lo que hace el código y los datos de data/. */
(function () {
  'use strict';
  var STRINGS = {
    es: {
      title: 'Metodología',
      sub: 'Cómo se verifican, fechan y convierten los datos, y cómo se calcula el índice compuesto.',
      sections: [
        { h: 'Principio: solo datos verificables', p: ['Cada cifra del panel viene de una fuente oficial o abierta, con su fecha y un enlace para comprobarla. Si no hay una serie trazable, no se muestra ningún valor: no rellenamos huecos con estimaciones ni con datos de muestra.'] },
        { h: 'Qué significan las etiquetas', id: 'etiquetas', ul: [
          { b: 'DATO OFICIAL.', t: 'Dato verificado en su fuente oficial, con fecha de observación y de publicación.' },
          { b: 'NO COMPARABLE.', t: 'El dato es real, pero su definición no equivale a la del otro mercado. Ejemplos: el precio de EE. UU. de cerdo, vacuno y pollo es en peso vivo, frente a la canal de la UE; los fertilizantes de la UE son índices agregados de nutriente, no un producto concreto. Se muestra con la etiqueta y no entra en comparaciones directas.' },
          { b: 'PENDIENTE.', t: 'Aún no hay una fuente verificable y con licencia adecuada. La tarjeta no muestra cifra hasta que la haya.' }
        ] },
        { h: 'Fuentes y frecuencia', ul: [
          { b: 'EE. UU. — USDA NASS (Quick Stats).', t: 'Precio recibido por el productor, mensual y nacional: trigo, maíz, arroz, leche, huevos, cerdo, vacuno y pollo. NASS publica una vez al mes; consultamos cada semana para no perder ninguna publicación.' },
          { b: 'UE — Comisión Europea, Agri-food Data Portal.', t: 'Precios semanales de mercado con España como referencia (cerdo, vacuno, cordero, pollo, huevos, cereales, aceite de oliva, azúcar, leche, harina de soja, fertilizantes). Los coeficientes por país se calculan con datos reales de la misma semana.' },
          { b: 'Reino Unido — Defra (Open Government Licence v3.0).', t: 'Leche e índices de precios agrarios, mensuales. Los precios semanales de cereales y ganado del Reino Unido los publica AHDB con términos que impiden su uso automático; por eso esas tarjetas figuran como pendientes.' },
          { b: 'Canadá — Statistics Canada (Open Government Licence – Canada).', t: 'Precios mensuales pagados al productor (tabla 32-10-0077-01): trigo, cebada, avena, canola, maíz, leche, vacuno, cerdo, cordero, pollo y huevos. La tabla solo da provincias, sin total nacional; cada producto usa una provincia de referencia (Saskatchewan, Alberta, Ontario o Quebec, indicada en la ficha). Moneda CAD; leche convertida de $/kilolitro a $/100 kg con densidad 1,03 kg/l. Comparabilidad direccional con EE. UU.' },
          { b: 'Canadá — Alberta Agriculture and Irrigation (Open Government Licence – Alberta).', t: 'Informes semanales de mercado de cultivos y ganado (PDF de formato fijo): ofertas de elevador de canola, trigo CWRS, trigo, cebada y avena forrajeros, ofertas al contado de lenteja Laird y guisante verde, novillos en ventas directas y cerdo al contado (índice 100, por kg de canal). Son precios ofrecidos por compradores, no operaciones cerradas; se publican por fecha de informe (viernes). No sustituyen a los precios mensuales de Statistics Canada, que tienen otra base.' },
          { b: 'Dinamarca — Statistics Denmark (CC BY 4.0).', t: 'Precios mensuales de granja (tabla LPRIS10, desde 2005) y leche en granja (ANI71, desde 1995) en coronas danesas (DKK), convertidos a euros con el tipo de cambio del BCE. Trigo, cebada, avena, centeno, colza, leche, cerdo, vacuno y pollo. Comparabilidad direccional: definiciones y calidades danesas, no idénticas a las de los precios europeos de referencia.' },
          { b: 'Países Bajos y Australia — CBS y ABS (CC BY 4.0).', t: 'Sin precios de granja publicados: solo producción, cultivos, sacrificio y exportaciones (página Producción por país). Se muestran tal como las publica la fuente.' },
          { b: 'Eurostat.', t: 'Índices de precios agrarios de la UE, trimestrales.' },
          { b: 'Eurostat — Comext (comercio exterior).', t: 'Base DS-045409 (comercio de la UE desde 1988 por capítulos del Sistema Armonizado), API de Comext. Ocho países declarantes (ES, FR, DE, BE, AT, PT, DK, NL). Total agroalimentario = suma de los capítulos 01 a 24; capítulos propios para animales vivos, carne, lácteos, hortalizas, fruta, cereales, oleaginosas, grasas, azúcar, bebidas, piensos y fertilizantes (31), más aceite de oliva (1509) y corcho (45) donde aplica. Mensual desde 2000 con socio «mundo» (incluye comercio dentro de la UE), con el total también separado en dentro y fuera de la UE. Socios: ranking de los 10 mayores del último año completo, por país y flujo, con serie anual desde 2002; producto por socio con los 6 últimos años completos. Valores en millones de euros, tal como los publica Eurostat, sin ajustar. El último mes y el último año se revisan. En Países Bajos y Bélgica una parte relevante es tránsito y reexportación. Actualización los días 16, 18 y 22 de cada mes.' },
          { b: 'USITC — Tarifa armonizada (HTS).', t: 'API REST de la USITC, edición vigente. Capítulos 01-24 y 31; una línea por código de 8 dígitos con arancel general (NMF), preferencias, columna 2 y unidades de las líneas estadísticas. Las medias ad valorem son simples (sin ponderar por comercio). Cuotas arancelarias y aranceles por orden ejecutiva no están en la tabla base: se resumen en una capa manual con fecha de vigencia.' },
          { b: 'CBSA, SNICE y TARIC — aranceles de importación.', t: 'México: fracciones arancelarias de la LIGIE (Excel de SNICE, arancel general de importación). Canadá: base de datos del Customs Tariff de la CBSA (MFN y preferencias CUSMA, CETA, CPTPP…; las líneas «within/over access commitment» se marcan como cuota). UE: medidas de importación del TARIC (derecho de tercer país erga omnes, preferencias de algunos socios y existencia de contingente). Mismo esquema que EE. UU.; capítulos 01-24 y 31; medias ad valorem simples sin ponderar. En la UE «cond.» indica derecho condicionado. Las medidas recientes de la UE (Rusia y Bielorrusia, Ucrania, Mercosur) van en una capa manual con fecha, contrastada con EUR-Lex, Access2Markets y el Consejo de la UE.' },
          { b: 'Banco Mundial — indicadores macro.', t: 'Indicadores NY.GDP.MKTP.CD, NY.GDP.PCAP.CD, SP.POP.TOTL, SL.UEM.TOTL.ZS y NV.AGR.TOTL.ZS (último año disponible). Deuda pública bruta de las administraciones (% PIB) de Eurostat gov_10dd_edpt1; en Canadá y Australia, deuda del gobierno central del Banco Mundial (no comparable). Actualización mensual.' },
          { b: 'Canadá — Statistics Canada (estadísticas ampliadas, Statistics Canada Open Licence).', t: 'Cultivos (32-10-0359), existencias (32-10-0007 y 32-10-0480), entregas y molturación (32-10-0351, 32-10-0352), ganadería, leche, huevos y aves, ingresos y renta agraria (32-10-0045, 32-10-0046, 32-10-0052), índices de precios (32-10-0098, 18-10-0258), fertilizantes (32-10-0038) y comercio exterior (12-10-0163 por producto, 12-10-0011 y 12-10-0173 por socio, 12-10-0175 por provincia y socio desde 2018), balance de granos al cierre de campaña (32-10-0013; el periodo es el año de cosecha) y vacuno y terneros (32-10-0125). Valores en la unidad de origen convertida a CAD millones, miles de toneladas o cabezas; base aduanera sin desestacionalizar en el comercio. El ranking de socios se recalcula en cada ejecución. Lunes y jueves.' },
          { b: 'España — MAPA (Encuestas ganaderas).', t: 'Efectivos de vacuno, ovino, caprino y porcino (ibérico y no ibérico) por provincia, censos de mayo y noviembre desde 2010, leídos del libro efectivos_ganado.xlsx que publica el MAPA. Se guardan tal cual (a un decimal); un valor negativo de la fuente queda como hueco y las filas de comunidad autónoma se ignoran. Reutilización citando la fuente. Semanal (jueves).' },
          { b: 'España — MAPA (balances de cereales).', t: 'Balance anual de trigo blando y duro, cebada, maíz, centeno, avena, sorgo y triticale por campaña (1 jul-30 jun) desde 2016/17: superficie, rendimiento, producción, existencias, importaciones, consumo interno y exportaciones, leídos de los PDF del MAPA. Cifras tal cual; celdas vacías sin dato; el estado (estimación, provisional) es el del PDF y las discrepancias de su columna Total se anotan. Reutilización citando la fuente. Semanal (jueves).' },
          { b: 'España — MAPA (balances del sector oleícola y aforo).', t: 'Balance de aceite de oliva, aceite de orujo (campaña 1 oct-30 sep) y aceituna de mesa (1 sep-31 ago) desde 2020/21: existencias, producción, importaciones, mercado interior, exportaciones, ajustes y pérdidas, leídos de los PDF del MAPA, con el desglose UE-27 y fuera de la UE cuando lo publica. Más el aforo de cosecha de aceite de oliva por comunidad autónoma (estimación publicada el 1 de octubre), que se rotula siempre como estimación. Cifras tal cual; existencias/salida es un cálculo de Dehesa Index y está rotulado. Reutilización citando la fuente. Semanal (jueves).' },
          { b: 'España — MAPA (leche cruda, INFOLAC).', t: 'Entregas mensuales de leche cruda a los primeros compradores (t), precio medio declarado (€/l, media ponderada sin IVA ni transporte), grasa y proteína (%), ganaderos y compradores, nacional y por comunidad autónoma, leídos del informe mensual del MAPA (declaraciones obligatorias, RD 319/2015). Cada informe cubre 12 meses y el archivo acumula historia (precio desde enero de 2022, entregas desde septiembre de 2024); el MAPA avisa de que los datos no están consolidados, así que un informe posterior puede revisar meses y prevalece el último. Meses sin dato = hueco, nunca cero. Reutilización citando la fuente. Semanal (jueves).' },
          { b: 'España — MAPA (sacrificio de ganado).', t: 'Cabezas sacrificadas y toneladas de peso canal por especie (vacuno, ovino, caprino, porcino, equino, aves y conejos), cada mes, nacional desde 2022 y por comunidad autónoma desde 2025, leídos del libro mensual de la Encuesta de sacrificio de ganado del MAPA. Aves y conejos se publican en miles de cabezas. El peso canal medio es un cálculo nuestro (t entre cabezas). Lo confidencial (DC) es hueco, nunca cero. En agosto de 2026 la fila Total de las hojas mensuales no coincide con la serie nacional: se usa la nacional y la diferencia se anota. Datos provisionales; prevalece el último libro. Reutilización citando la fuente. Semanal (jueves).' },
          { b: 'España — MAPA (sacrificio de ganado por provincia).', t: 'Cabezas sacrificadas y toneladas de peso canal por especie y provincia, cada año de 2004 a 2025, leídas de los libros anuales de la Encuesta de sacrificio de ganado en mataderos (hojas de cabezas y de carne; .xls hasta 2022 y .xlsx desde 2023). Se asignan a la provincia del matadero, no a la de cría. Aves y conejos van en miles de cabezas hasta 2024 y en cabezas desde 2025: aquí todo en cabezas. Lo confidencial (DC) es hueco, nunca cero, y no se estima restando aunque el total de la comunidad lo incluya. «España» es la fila publicada, que suma las provincias y los otros sacrificios sin provincia (grandes en ovino y caprino hasta 2007). Hasta 2013 el libro no distingue censo y muestra y 2007, 2012, 2013 y 2015 dicen «datos sin elevar»; desde 2016 es censal. El total nacional de 2022 a 2025 coincide con el de la serie mensual. Reutilización citando la fuente. Semanal (jueves).' },
          { b: 'España — MAPA (vino, INFOVI).', t: 'Entrada de uva (t), producción de vino por categoría (DOP, IGP, varietal, sin indicación geográfica) y color, salidas (exportaciones declaradas e interiores) y existencias de vino y mosto a 31 de julio (hl), por campaña (1 ago–31 jul) y comunidad, leídas del informe ampliado de julio del INFOVI del MAPA (desde la campaña 2020/21). Son declaraciones de las bodegas, no un balance del sector; el MAPA da las exportaciones como orientativas. Un informe nuevo sustituye al de su campaña y las revisiones se anotan. Hueco = hueco, nunca cero. Reutilización citando la fuente. Semanal (jueves).' },
          { b: 'España — MAPA (vino mensual, INFOVI).', t: 'Existencias iniciales y finales de vino y mosto, producción del mes, entradas y salidas por destino (interiores, UE y terceros países) en hl, por mes (desde enero de 2021) y comunidad, leídas del informe mensual del INFOVI del MAPA. Perímetro más estrecho que el de campaña (operadores que declaran cada mes), así que no se mezcla con él. El mes se lee del título de cada libro, que no tiene nombre fijo. Un mes sin libro es un hueco; un cuadro ausente, sin dato (nunca cero). Las diferencias del 0,2–1 % entre el cierre de un mes y la apertura del siguiente son revisiones del MAPA y se avisan. Reutilización citando la fuente. Semanal (jueves).' },
          { b: 'España — MAPA (balance del vino, histórico).', t: 'Balance oficial del vino de las campañas 2009/10 a 2015/16 en miles de hl: existencias, producción, importaciones, exportaciones, utilización interior y existencias finales, nacional, de los libros del MAPA. Las celdas vacías son hueco, nunca cero; el definitivo sustituye al provisional (2015/16 es provisional). No hay desglose por comunidad ni balance de 2016/17 a 2019/20, y no es comparable con las declaraciones INFOVI.' },
          { b: 'Energía y fertilizantes.', t: 'Diésel de EE. UU. (EIA, semanal) y de la UE (Oil Bulletin, semanal); gas natural (EIA semanal; Banco Mundial mensual), petróleo WTI y Brent (EIA, semanal); urea (Banco Mundial, mensual).' },
          { b: 'Clima — NASA POWER.', t: 'Lluvia y temperatura mensuales (reanálisis MERRA-2) en 31 puntos representativos de regiones productoras, comparadas con la media 2001-2020 del mismo mes, con histórico mensual desde 2000. Los meses más recientes los calcula NASA con otro flujo de procesamiento (GEOS-IT) que puede revisarse. Es contexto climático (una celda de unos 50 km, no una estación ni la región entera); no predice cosechas ni precios.' },
          { b: 'Oferta y demanda — USDA PSD.', t: 'Balances por país y campaña de cereales, oleaginosas, carne, leche y azúcar (licencia CC BY 4.0), mensuales con el WASDE.' },
          { b: 'Harina de soja de EE. UU. — USDA AMS.', t: 'Precio semanal de la harina de soja (Iowa, FOB, 46,5-48 % de proteína) del informe 3511 de USDA AMS Market News, en tonelada corta. Es un mercado regional, no un futuro; la comparación con Europa es orientativa.' },
          { b: 'Tipos de cambio.', t: 'Cotizaciones de referencia del Banco Central Europeo, cada día laborable.' }
        ] },
        { h: 'Fechas: observación y publicación', p: ['Cada dato lleva dos fechas: la de observación (el periodo al que se refiere) y la de publicación (cuándo lo publicó la fuente). Algunas fuentes no informan de su fecha de publicación; en ese caso registramos el día en que recogimos el dato por primera vez y lo anotamos en la ficha.'] },
        { h: 'Monedas y unidades', p: ['Los datos se guardan en la moneda y la unidad de la fuente. Para compararlos, el panel los convierte con el tipo de cambio de referencia del BCE del último día laborable y con factores de unidad fijos y visibles (por ejemplo, 1 docena de huevos = 0,6804 kg). Una conversión no vuelve comparable un dato que no lo es.'] },
        { h: 'Tipos de interés, divisas y su procedencia', p: ["Los tipos oficiales de EE. UU., la zona euro, Canadá y Australia vienen de los bancos centrales: BCE (facilidad de depósito), Bank of Canada (API Valet) y Reserve Bank of Australia (tabla F1.1); el de EE. UU. (tipo de los fondos federales) llega a través del conjunto WS_CBPOL del Bank for International Settlements (BIS), que recoge la serie de la Reserva Federal. La conversión a euros usa las medias mensuales históricas del BCE (USD, CAD, AUD, GBP y DKK desde 1999): cada valor se convierte con la media de su propio mes y se marca como conversión, nunca como dato de la fuente."] },
        { h: "Reproducibilidad, revisiones y cobertura", p: ["Cada serie lleva su linaje (fichero, flujo de actualización y última ejecución, visibles en la página de estado). Los cambios en periodos ya publicados se detectan y se guardan (data/revisions.json); pueden ser revisiones de la fuente, correcciones o reajustes del histórico, y la fuente no los confirma, y con git se puede reconstruir qué valor mostraba el sitio en una fecha concreta (script reconstruct-indicator). El Coverage Score de cada país mide qué categorías tienen datos, cuántos están al día y cuántos periodos acumulan. Cuando una misma serie llega de varias fuentes, se muestra la de mayor prioridad (nacional, después Eurostat, internacional y secundaria) y las demás quedan registradas, sin duplicar."] },
        { h: 'Estado de los cultivos', id: 'cultivos', p: ['Viene del informe semanal Crop Progress de USDA NASS (API Quick Stats), que se publica los lunes por la tarde, hora de EE. UU., aproximadamente de abril a noviembre (el trigo de invierno también se valora en otoño). La valoración es el porcentaje de superficie en cada categoría —muy mala, mala, regular, buena, excelente—; "buena + excelente" es la suma de las dos últimas. La dan corresponsales locales de NASS, así que es subjetiva y no es una previsión de cosecha ni de precios. El avance es el porcentaje de superficie que ha llegado a cada etapa (sembrado, cosechado...). La media de 5 años y la comparación con el año pasado son cálculo propio de Dehesa Index: se toma la misma fecha en las campañas anteriores, interpolando entre informes semanales, y solo se calcula si hay dato en al menos 4 de las 5 campañas. Una etapa ya completada (100 %) se mantiene en 100 % en las semanas siguientes. Los valores que NASS no publica no se rellenan.'] },
        { h: 'Mercados USDA', id: 'mercados', p: ['Precios de mercado de EE. UU. tal como los publica USDA AMS Market News (API MARS): piensos y subproductos, etanol y coproductos, granos, oleaginosas, legumbres, arroz, aves, huevos, carne y subproductos, cerdos de recría, ganado de venta directa, heno y lácteos. Se leen a diario de lunes a viernes (algunos informes son semanales). Cada serie es una combinación fija de producto, calidad, lugar y unidad del propio informe; si en un mismo día o semana hay dos cifras distintas para la misma serie, ese punto se descarta en lugar de adivinar. No se convierten monedas ni unidades. Cuando el informe da un precio medio se muestra ese; cuando solo da mínimo y máximo se muestra el punto medio, marcado con ≈. Son datos oficiales pero no son un índice de Dehesa Index ni son comparables con los europeos: cada informe tiene su propia base de lugar, calidad y entrega.'] },
        { h: 'Precios locales del grano (EE. UU.)', id: 'precios-locales', p: ['Las ofertas de compra en efectivo (cash bids) vienen de los informes de grano de USDA AMS Market News (API MARS), que se leen en CI; la clave de la API nunca llega al navegador. Cada precio indica qué representa: una región del estado, un terminal, un mercado de exportación o el estado entero. Dehesa Index no presenta un dato como «elevador local» salvo que el informe identifique el elevador, y no coloca puntos en un mapa sin ubicación real. Cada serie es una combinación fija de producto, clase de trigo, calidad, tipo de comprador, periodo de entrega y unidad; HRW, SRW, HRS y durum no se mezclan. Se muestra el precio medio cuando el informe lo da, el precio exacto si mínimo y máximo coinciden y, si no, el rango; nunca un punto medio calculado. La base solo aparece cuando USDA la publica y nunca se calcula. La variación solo se calcula entre observaciones consecutivas próximas (7 días en informes diarios, 14 en semanales). Si USDA corrige un precio ya publicado, se guarda el valor anterior, el nuevo y la fecha de detección. Si la API falla, se conserva el último dato válido y se marca su frescura. No se calcula un premio/descuento frente a la referencia nacional porque el precio de referencia de EE. UU. de Dehesa es mensual (NASS) y no es comparable con ofertas diarias. «Cerca de mí»: el código postal se convierte en estado con una tabla local (ZCTA del Censo 2000, solo estado); se procesa en tu navegador y no se guarda ni se envía. Premium orgánico (fichas de maíz, soja y trigo): mediana de ofertas orgánicas de USDA AMS 3802 menos mediana de ofertas convencionales con la misma especificación (producto, clase, grado, elevador y tipo de oferta) en la misma fecha; solo si hay al menos 3 series orgánicas y 5 convencionales. Es indicativo: son dos informes distintos y su cobertura regional y mes de entrega pueden diferir.'] },
        { h: 'Exportaciones de EE. UU.', id: 'exportaciones', p: ['Las ventas de exportación semanales vienen del informe Export Sales Reporting de USDA FAS (API abierta de FAS), que se publica los jueves y cubre trigo, maíz, sorgo, cebada, soja y derivados, algodón, arroz, vacuno y cerdo. Las cifras son toneladas métricas (algodón en balas) que las empresas declaran a USDA: «exportado» son los embarques acumulados de la campaña, «ventas pendientes» las ya cerradas y sin embarcar, y «compromiso total» su suma. Los totales suman los destinos publicados y el agregado de la UE cuenta como un solo destino. El comercio mensual por país viene de USDA FAS GATS, con datos del Census Bureau de EE. UU.: solo comercio de EE. UU. con cada país (no flujos entre terceros), en dólares corrientes y, cuando el Census mide en kilos, en toneladas; se incluyen los socios agrarios principales, no todos los países. Los grupos de producto se forman con capítulos arancelarios (HS) y son aproximados. Los dos últimos meses pueden revisarse. Datos públicos del Gobierno de EE. UU.; no se convierten ni se comparan con precios.'] },
        { h: 'Ficha de producto', id: 'producto', p: ['La ficha de producto (trigo, maíz, soja, arroz, vacuno, cerdo, leche y pollo) no crea datos nuevos: reúne en una página lo que ya publica cada bloque, con su fuente y su unidad (precios, oferta y demanda, ventas de exportación, comercio por país, cultivo o existencias de ganado, sequía y costes). Los mercados no se convierten ni se suman: el precio de EE. UU. de vacuno y cerdo es peso vivo y no equivale al precio en canal europeo. La media de sequía ponderada por producción es un cálculo de Dehesa con los 5 mayores estados productores y expresa el porcentaje de superficie del estado en sequía moderada o peor, no de la superficie cultivada. Si un bloque no tiene dato, no aparece. En soja, el precio mostrado es el de la harina de soja (no del grano).'] },
        { h: 'Precios de la UE', id: 'europa', p: ['La página Precios de la UE reúne todas las series de precios que publica la Comisión Europea en su Agri-food Data Portal (API pública): cereales, oleaginosas y tortas, lácteos, vacuno, cerdo, pollo, huevos, cordero, arroz, leche cruda, aceite de oliva, azúcar, vino, fruta y hortaliza (solo media nacional, en tres etapas de la cadena) y fertilizantes, país por país. Cada línea es el precio que publica el portal, en su propia unidad (€/t, €/100 kg, €/hl…), sin convertir y sin promediar mercados; si un país publica varios mercados, cada uno se muestra por separado, y las filas que no están en euros se descartan. «UE» es un agregado calculado por la Comisión, no por Dehesa Index. El portal no publica la fecha en que sube cada dato ni los precios de todos los países cada semana, por eso algunos países tienen huecos. Se actualiza los jueves; el histórico llega hasta 2015 en la mayoría de familias (desde 2021 en cereales y vacuno) y, en azúcar, vino y fertilizantes, hasta donde publica la fuente.'] },
        { h: 'Monitor de sequía de EE. UU.', id: 'sequia', p: ['El porcentaje de superficie de cada estado en sequía viene del U.S. Drought Monitor, elaborado por el National Drought Mitigation Center (Universidad de Nebraska-Lincoln) con USDA y NOAA. Se publica los jueves con el mapa válido al martes anterior. Se muestran las categorías D0–D4 tal como las publica la API (acumuladas: D1 incluye D2, D3 y D4); las variaciones se calculan restando porcentajes (puntos porcentuales) frente a la semana anterior y frente a 52 semanas antes. Es una valoración, no un pronóstico.'] },
        { h: 'Ganadería y lácteo de EE. UU.', id: 'ganaderia', p: ['Los censos de cerdos y vacuno, la producción de leche por estado y las existencias en frío vienen de USDA NASS (Quick Stats: Hogs and Pigs, Cattle, Milk Production y Cold Storage) y se muestran tal como se publican, en su unidad original. Las encuestas de cerdos son trimestrales, las de vacuno semestrales, y la leche y las existencias en frío mensuales. Los datos por estado solo se muestran cuando NASS los publica para el mismo periodo. Las variaciones son cambios porcentuales simples entre dos datos publicados.'] },
        { h: 'Costes de los insumos agrarios de EE. UU.', id: 'insumos', p: ['Los índices de precios pagados por los agricultores (fertilizantes, combustibles, piensos, agroquímicos, semillas, maquinaria, servicios, salarios, alquiler e intereses) vienen de USDA NASS, Agricultural Prices (Quick Stats), con base 2011 = 100. NASS ya no publica precios absolutos de fertilizantes ni combustibles, así que se muestran los índices oficiales; no se estiman precios por tonelada ni por litro. Las variaciones son porcentuales entre índices publicados.'] },
        { h: 'Alimentos, costes y renta agraria de EE. UU.', id: 'costes', p: ['Los precios de alimentos (previsión de IPC e IPP), los costes y rentabilidad por cultivo y ganado, la previsión de costes y la renta agraria vienen de los ficheros oficiales del USDA Economic Research Service (Food Price Outlook, Commodity Costs and Returns, Cost of Production Forecasts y Farm Income and Wealth Statistics). Se muestran tal como se publican; el último año de renta agraria y las previsiones de precios y costes son previsiones del ERS. El punto de equilibrio por unidad se calcula en Dehesa dividiendo el total de costes por acre por el rendimiento por acre, y así se indica en la página.'] },
        { h: 'Rendimientos y superficie por estado de EE. UU.', id: 'rendimientos', p: ['El rendimiento por acre, la superficie sembrada y cosechada y la producción por estado vienen de USDA NASS (Quick Stats, encuestas Crop Production y Acreage), en sus unidades originales (acres, bushels, libras). Los datos por condado (encuesta de condados de NASS, vía Quick Stats, actualizados una vez al mes) solo existen para los cultivos y condados que NASS publica; cada año cambian y los condados sin cifra se muestran en gris, nunca como cero. «Otros condados» es la suma que NASS no desglosa. Los contornos son del Censo de EE. UU. (dominio público, vía us-atlas). El último año puede ser una estimación o previsión de NASS hasta que se cierre la campaña; los estados sin dato publicado no se rellenan.'] },
        { h: 'Manitoba: ganado, ovino, caprino y porcino', id: 'manitoba', p: ['Los precios de las subastas de vacuno, ovino y caprino y el porcino de las procesadoras de Manitoba vienen de los informes semanales (PDF) de Manitoba Agriculture, con licencia OpenMB (atribución obligatoria). Cada informe se lee con un lector que se niega a publicar lo que no cuadra: cabezas que no suman, mínimo, media y máximo fuera de orden, fechas imposibles, precios fuera de rango. Las cabras las publicó Manitoba por cabeza y desde abril de 2025 las convierte a C$/cwt con pesos medios que estima ella misma; solo se aceptan cuando el informe lo rotula así. Si dos informes dan cifras distintas para la misma venta, la celda se deja vacía (un hueco, nunca un cero). Los cambios comparan siempre la misma serie con sus fechas; no se mezclan con el histórico mensual de Canfax, que no se utiliza.'] },
        { h: 'Oferta y demanda', id: 'oferta-demanda', p: ['Los balances de producción, consumo, comercio y existencias vienen de USDA Foreign Agricultural Service (PSD Online, licencia CC BY 4.0) y se actualizan con el informe mensual WASDE. La campaña indicada (2025) es la que empieza ese año (2025/26); la más reciente es una previsión que USDA revisa cada mes. "Mundo" es la suma de los países de la base PSD, contando la UE una sola vez; no es una cifra publicada por USDA. Las campañas comerciales no coinciden entre países, y exportaciones e importaciones se declaran por separado, así que el comercio mundial no siempre cuadra. Las cifras van en miles de toneladas (carne en equivalente canal). Sin dato en PSD, no se pinta nada.'] },
        { h: 'Dehesa Index: el índice compuesto', id: 'indice', p: ['Es un índice mensual con base 100 en octubre de 2024, para el mercado de la UE (con los pesos de abajo). EE. UU. tiene su propio índice, con la misma base y método, construido con USDA NASS, USDA AMS y EIA; no incluye el grupo de fertilizantes (no hay serie verificada) y reescala el resto de pesos; usa petróleo WTI en lugar de Brent y no incluye cordero. Canadá también tiene el suyo, con precios al productor de Statistics Canada en dólares canadienses; no incluye pienso, fertilizantes ni energía (no hay series verificadas con historia suficiente), reescala el resto de pesos y su último mes es el último con dato de todas las series, porque Statistics Canada publica con unos dos meses de retraso. Cada serie verificada se convierte a media mensual y se reexpresa a base 100; cada grupo es la media simple de sus series; el índice es la media ponderada de los grupos: Cereales 25 %, Ganadería 25 %, Lácteos 15 %, Pienso 15 %, Fertilizantes 10 %, Energía 10 %.', 'Como cada serie se reexpresa en su propia unidad, el índice mide evolución, no es un precio y no mezcla monedas. Si una serie tiene un mes sin dato en el origen, se arrastra el mes anterior y queda declarado en el archivo de datos. El Reino Unido se añadirá cuando tenga al menos 24 meses de historia. El panel «Crea tu propio índice» permite cambiar los pesos y compararlos con el oficial.'] },
        { h: 'Limitaciones', ul: [
          { t: 'No son precios en tiempo real: la frecuencia la marca cada fuente (semanal, mensual o trimestral).' },
          { t: 'Los precios de EE. UU. (NASS) son al productor y los de la UE son de mercado; aunque se muestren en la misma moneda, no son siempre el mismo concepto.' },
          { t: 'Las fuentes pueden revisar sus datos o cambiar sus definiciones; reflejamos la última versión publicada.' },
          { t: 'Nada de esto es asesoramiento financiero ni de inversión.' }
        ] },
        { h: 'Datos abiertos y correcciones', p: ['Los archivos con los que se construye el panel están publicados en la carpeta de datos del sitio (JSON y CSV), con la fuente y la metodología de cada serie. Si ves un error o una definición mejorable, escríbenos a hola@dehesaindex.com.'] }
      ],
      links: [{ href: 'clima.html', t: 'Clima agrícola' }, { href: 'data/', t: 'Datos abiertos' }, { href: 'legal.html', t: 'Aviso legal y privacidad' }, { href: 'informacion.html', t: 'Información' }]
    },
    en: {
      title: 'Methodology',
      sub: 'How data is verified, dated and converted, and how the composite index is calculated.',
      sections: [
        { h: 'Principle: verifiable data only', p: ['Every figure on the dashboard comes from an official or open source, with its date and a link to check it. If there is no traceable series, no value is shown: we do not fill gaps with estimates or sample data.'] },
        { h: 'What the labels mean', id: 'etiquetas', ul: [
          { b: 'OFFICIAL DATA.', t: 'Data verified at its official source, with observation and publication dates.' },
          { b: 'NOT COMPARABLE.', t: 'The data is real, but its definition is not equivalent to the other market’s. Examples: U.S. hog, cattle and chicken prices are live weight, versus EU carcass weight; EU fertiliser figures are aggregated nutrient indices, not a specific product. It is shown with the label and left out of direct comparisons.' },
          { b: 'PENDING.', t: 'There is no verifiable, properly licensed source yet. The card shows no figure until there is one.' }
        ] },
        { h: 'Sources and frequency', ul: [
          { b: 'U.S. — USDA NASS (Quick Stats).', t: 'Price received by farmers, monthly and national: wheat, corn, rice, milk, eggs, hogs, cattle and chicken. NASS publishes once a month; we check every week so no release is missed.' },
          { b: 'EU — European Commission, Agri-food Data Portal.', t: 'Weekly market prices with Spain as the reference (pork, beef, lamb, chicken, eggs, cereals, olive oil, sugar, milk, soya meal, fertilisers). Country coefficients are computed from real same-week data.' },
          { b: 'UK — Defra (Open Government Licence v3.0).', t: 'Milk and agricultural price indices, monthly. Weekly UK cereal and livestock prices are published by AHDB under terms that prevent automated use, so those cards are shown as pending.' },
          { b: 'Canada — Statistics Canada (Open Government Licence – Canada).', t: 'Monthly prices paid to producers (table 32-10-0077-01): wheat, barley, oats, canola, corn, milk, cattle, hogs, lambs, chicken and eggs. The table only has provinces, no national total; each product uses a reference province (Saskatchewan, Alberta, Ontario or Quebec, shown on the card). Currency CAD; milk converted from $/kilolitre to $/100 kg at 1.03 kg/l. Directional comparability with the U.S.' },
          { b: 'Canada — Alberta Agriculture and Irrigation (Open Government Licence – Alberta).', t: 'Weekly crop and livestock market reviews (fixed-format PDFs): elevator bids for canola, CWRS wheat, feed wheat, barley and oats, cash bids for Laird lentils and green peas, direct-sale steers and cash hogs (index 100, per kg carcass). These are prices bid by buyers, not closed trades; they are dated by report (Friday). They do not replace the monthly Statistics Canada prices, which use a different basis.' },
          { b: 'Denmark — Statistics Denmark (CC BY 4.0).', t: 'Monthly farm prices (table LPRIS10, since 2005) and milk ex farm (ANI71, since 1995) in Danish kroner (DKK), converted to euros with the ECB rate. Wheat, barley, oats, rye, rapeseed, milk, pigs, young bulls and broilers. Directional comparability: Danish definitions and grades, not identical to the European reference prices.' },
          { b: 'Netherlands and Australia — CBS and ABS (CC BY 4.0).', t: 'No farm prices published: only production, crops, slaughter and exports (Production by country page), shown as published by the source.' },
          { b: 'Eurostat.', t: 'EU agricultural price indices, quarterly.' },
          { b: 'Eurostat — Comext (foreign trade).', t: 'Dataset DS-045409 (EU trade since 1988 by Harmonised System chapter), Comext API. Eight reporting countries (ES, FR, DE, BE, AT, PT, DK, NL). Agri-food total = sum of HS chapters 01 to 24; own series for live animals, meat, dairy, vegetables, fruit, cereals, oilseeds, fats, sugar, beverages, feed and fertilisers (31), plus olive oil (1509) and cork (45) where applicable. Monthly since 2000 with partner “world” (includes intra-EU trade), with the total also split into intra- and extra-EU. Partners: ranking of the 10 largest of the latest complete year, by country and flow, with an annual series since 2002; product by partner covers the last 6 complete years. Values in EUR million as published by Eurostat, unadjusted. The latest month and year are revised. For the Netherlands and Belgium a relevant share is transit and re-exports. Updated on the 16th, 18th and 22nd of each month.' },
          { b: 'USITC — Harmonized Tariff Schedule (HTS).', t: 'USITC REST API, current release. Chapters 01-24 and 31; one line per 8-digit code with general (MFN) rate, preferences, column 2 and units from the statistical lines. Ad valorem averages are simple (not trade-weighted). Tariff-rate quotas and executive-order duties are not in the base table: they are summarised in a manual layer with effective dates.' },
          { b: 'CBSA, SNICE and TARIC — import tariffs.', t: 'Mexico: LIGIE tariff lines (SNICE Excel, general import rate). Canada: CBSA Customs Tariff database (MFN and CUSMA, CETA, CPTPP… preferences; “within/over access commitment” lines are flagged as quota). EU: TARIC import measures (erga omnes third-country duty, selected partner preferences and quota existence). Same schema as the US; chapters 01-24 and 31; simple unweighted ad valorem averages. In the EU “cond.” means a conditional duty. Recent EU measures (Russia and Belarus, Ukraine, Mercosur) sit in a dated manual layer checked against EUR-Lex, Access2Markets and the Council of the EU.' },
          { b: 'World Bank — macro indicators.', t: 'Indicators NY.GDP.MKTP.CD, NY.GDP.PCAP.CD, SP.POP.TOTL, SL.UEM.TOTL.ZS and NV.AGR.TOTL.ZS (latest available year). General government gross debt (% of GDP) from Eurostat gov_10dd_edpt1; for Canada and Australia, World Bank central government debt (not comparable). Monthly update.' },
          { b: 'Canada — Statistics Canada (extended statistics, Statistics Canada Open Licence).', t: 'Crops (32-10-0359), stocks (32-10-0007 and 32-10-0480), deliveries and crush (32-10-0351, 32-10-0352), livestock, milk, eggs and poultry, farm cash receipts and income (32-10-0045, 32-10-0046, 32-10-0052), price indices (32-10-0098, 18-10-0258), fertilisers (32-10-0038) and foreign trade (12-10-0163 by product, 12-10-0011 and 12-10-0173 by partner, 12-10-0175 by province and partner from 2018), grain supply and disposition at crop-year end (32-10-0013; the period is the harvest year) and cattle and calves (32-10-0125). Values converted from the source unit to CAD million, thousand tonnes or head; trade is customs-based and not seasonally adjusted. The partner ranking is recalculated on every run. Mondays and Thursdays.' },
          { b: 'Spain — MAPA (livestock surveys).', t: 'Cattle, sheep, goat and pig (Iberian and non-Iberian) numbers by province, May and November censuses since 2010, read from the efectivos_ganado.xlsx workbook published by MAPA. Stored as published (to one decimal); a negative source value is left as a gap and autonomous-community rows are ignored. Reuse with source citation. Weekly (Thursday).' },
          { b: 'Spain — MAPA (cereal balances).', t: 'Annual balance of common and durum wheat, barley, maize, rye, oats, sorghum and triticale by marketing year (1 Jul-30 Jun) since 2016/17: area, yield, production, stocks, imports, domestic use and exports, read from MAPA PDFs. Figures as published; empty cells are no data; the status (estimate, provisional) is the PDF’s and discrepancies in its Total column are noted. Reuse with source citation. Weekly (Thursday).' },
          { b: 'Spain — MAPA (olive sector balances and harvest forecast).', t: 'Balance of olive oil, pomace oil (1 Oct-30 Sep marketing year) and table olives (1 Sep-31 Aug) since 2020/21: stocks, production, imports, domestic market, exports, adjustments and losses, read from MAPA’s PDFs, with the EU-27 / non-EU split when published. Plus the olive oil harvest forecast by region (an estimate published on 1 October), always labelled as an estimate. Figures as published; stocks-to-outflow is a Dehesa Index calculation and is labelled. Reuse with attribution. Weekly (Thursday).' },
          { b: 'Spain — MAPA (raw milk, INFOLAC).', t: 'Monthly raw milk deliveries to first buyers (t), average declared price (€/l, weighted mean excluding VAT and transport), fat and protein (%), farmers and buyers, national and by autonomous community, read from MAPA’s monthly report (mandatory declarations, RD 319/2015). Each report covers 12 months and the file accumulates history (price since January 2022, deliveries since September 2024); MAPA warns the data are not consolidated, so a later report may revise months and the latest prevails. Months without data are gaps, never zero. Reuse with attribution. Weekly (Thursday).' },
          { b: 'Spain — MAPA (livestock slaughter).', t: 'Head slaughtered and tonnes of carcass weight by species (cattle, sheep, goats, pigs, equines, poultry and rabbits), every month, national since 2022 and by autonomous community since 2025, read from the monthly workbook of MAPA’s Livestock Slaughter Survey. Poultry and rabbits are published in thousands of head. Average carcass weight is our own calculation (t divided by head). Confidential data (DC) are gaps, never zero. In August 2026 the Total row of the monthly sheets does not match the national series: the national one is used and the difference is recorded. Provisional data; the latest workbook prevails. Reuse with attribution. Weekly (Thursday).' },
          { b: 'Spain — MAPA (slaughter by province).', t: 'Head slaughtered and tonnes of carcass weight by species and province, every year from 2004 to 2025, read from the annual workbooks of the Slaughterhouse Livestock Survey (head and meat sheets; .xls until 2022 and .xlsx from 2023). They are assigned to the slaughterhouse province, not where the animal was raised. Poultry and rabbits are in thousands of head until 2024 and in head from 2025: here all in head. Confidential data (DC) are gaps, never zero, and are not estimated by subtraction even though the region total includes them. “Spain” is the published row, which adds the provinces and the other slaughter with no province (large for sheep and goats until 2007). Until 2013 the workbook does not say census or sample, and 2007, 2012, 2013 and 2015 say “unraised data”; from 2016 it is a census. The national total for 2022 to 2025 matches the monthly series. Reuse with attribution. Weekly (Thursday).' },
          { b: 'Spain — MAPA (wine, INFOVI).', t: 'Grape intake (t), wine production by category (PDO, PGI, varietal, no geographical indication) and colour, outflows (declared exports and domestic) and wine and must stocks at 31 July (hl), by campaign (1 Aug–31 Jul) and region, read from MAPA’s INFOVI July extended report (from the 2020/21 campaign). These are winery declarations, not a sector balance; MAPA gives exports as indicative. A new report replaces its campaign’s and revisions are logged. A gap is a gap, never zero. Reuse with attribution. Weekly (Thursday).' },
          { b: 'Spain — MAPA (monthly wine, INFOVI).', t: 'Opening and closing stocks of wine and must, production in the month, inflows and outflows by destination (domestic, EU and third countries) in hl, by month (since January 2021) and region, read from MAPA’s monthly INFOVI report. A narrower scope than the campaign figures (operators reporting every month), so the two are not mixed. The month is read from each workbook’s title, since file names are not fixed. A month without a workbook is a gap; a missing table is no data (never zero). Differences of 0.2–1 % between one month’s close and the next month’s opening are MAPA revisions and are flagged. Reuse with attribution. Weekly (Thursday).' },
          { b: 'Spain — MAPA (wine balance, historical).', t: 'Official wine balance for the 2009/10 to 2015/16 campaigns in thousand hl: stocks, production, imports, exports, domestic use and closing stocks, national, from MAPA workbooks. Empty cells are gaps, never zero; the final figure replaces the provisional one (2015/16 is provisional). There is no breakdown by region and no balance for 2016/17 to 2019/20, and it is not comparable with the INFOVI declarations.' },
          { b: 'Energy and fertilisers.', t: 'U.S. diesel (EIA, weekly) and EU diesel (Oil Bulletin, weekly); natural gas (EIA weekly; World Bank monthly), WTI and Brent crude (EIA, weekly); urea (World Bank, monthly).' },
          { b: 'Climate — NASA POWER.', t: 'Monthly rainfall and temperature (MERRA-2 reanalysis) at 31 representative points in producing regions, compared with the 2001-2020 average for the same month, with monthly history since 2000. The most recent months are computed by NASA with a different processing stream (GEOS-IT) that may be revised. It is climate context (a ~50 km grid cell, not a station or the whole region); it does not forecast crops or prices.' },
          { b: 'Supply and demand — USDA PSD.', t: 'Country balances by marketing year for grains, oilseeds, meat, milk and sugar (CC BY 4.0 licence), monthly with the WASDE.' },
          { b: 'US soybean meal — USDA AMS.', t: 'Weekly soybean meal price (Iowa, FOB, 46.5-48% protein) from USDA AMS Market News report 3511, per short ton. It is a regional market, not a futures price; the comparison with Europe is indicative.' },
          { b: 'Exchange rates.', t: 'European Central Bank reference rates, every business day.' }
        ] },
        { h: 'Dates: observation and publication', p: ['Each data point carries two dates: observation (the period it refers to) and publication (when the source released it). Some sources do not report a publication date; in that case we record the day we first collected the data and note it on the card.'] },
        { h: 'Currencies and units', p: ['Data is stored in the source’s currency and unit. To compare, the dashboard converts it using the ECB reference rate of the latest business day and fixed, visible unit factors (for example, 1 dozen eggs = 0.6804 kg). A conversion does not make a non-comparable figure comparable.'] },
        { h: 'Interest rates, currencies and their provenance', p: ["Official rates for the US, the euro area, Canada and Australia come from central banks: the ECB (deposit facility), the Bank of Canada (Valet API) and the Reserve Bank of Australia (table F1.1); the US rate (federal funds rate) comes through the Bank for International Settlements (BIS) WS_CBPOL dataset, which carries the Federal Reserve series. Conversion to euros uses ECB historical monthly averages (USD, CAD, AUD, GBP and DKK since 1999): each value is converted at the average of its own month and is labelled as a conversion, never as source data."] },
        { h: "Reproducibility, revisions and coverage", p: ["Every series carries its lineage (file, update workflow and last run, shown on the status page). Changes in already-published periods are detected and stored (data/revisions.json); they may be source revisions, corrections or rebuilds of the history, and the source does not confirm which, and git history lets us reconstruct what the site showed on a given date (reconstruct-indicator script). Each country’s Coverage Score measures which categories have data, how many are up to date and how many periods they hold. When the same series arrives from several sources, the highest-priority one is shown (national, then Eurostat, international, secondary) and the others are recorded, not duplicated."] },
        { h: 'Crop conditions', id: 'cultivos', p: ['This comes from USDA NASS’s weekly Crop Progress report (Quick Stats API), published Monday afternoons U.S. time, roughly April to November (winter wheat is also rated in autumn). The rating is the share of acreage in each category — very poor, poor, fair, good, excellent —; “good + excellent” is the sum of the last two. It is given by local NASS reporters, so it is subjective and not a crop or price forecast. Progress is the share of acreage that has reached each stage (planted, harvested...). The 5-year average and the year-ago comparison are Dehesa Index’s own calculation: the same date in earlier seasons is taken, interpolating between weekly reports, and only computed if at least 4 of the 5 seasons have data. A completed stage (100 %) stays at 100 % in later weeks. Values NASS does not publish are not filled in.'] },
        { h: 'USDA markets', id: 'mercados', p: ['U.S. market prices as published by USDA AMS Market News (MARS API): feed and by-products, ethanol and co-products, grains, oilseeds, pulses, rice, poultry, eggs, meat and by-products, feeder pigs, direct cattle, hay and dairy. They are read every weekday (some reports are weekly). Each series is a fixed combination of product, quality, place and unit from the report itself; if a single day or week has two different figures for the same series, that point is dropped rather than guessed. Currencies and units are not converted. When a report gives an average price that is shown; when it only gives a minimum and maximum the midpoint is shown, flagged with ≈. The data is official but is not a Dehesa Index measure and is not comparable with European data: each report has its own basis of place, quality and delivery.'] },
        { h: 'Local grain prices (US)', id: 'precios-locales', p: ['Cash bids come from USDA AMS Market News grain reports (MARS API), read in CI; the API key never reaches the browser. Each price states what it represents: a region of the state, a terminal, an export market or the whole state. Dehesa Index does not present a figure as a “local elevator” unless the report identifies the elevator, and it places no map points without a real location. Each series is a fixed combination of commodity, wheat class, grade, buyer type, delivery period and unit; HRW, SRW, HRS and durum are never mixed. The average is shown when the report gives one, the exact price when low and high coincide and otherwise the range; never a computed midpoint. Basis appears only when USDA publishes it and is never calculated. Change is only computed between close consecutive observations (7 days for daily reports, 14 for weekly). If USDA corrects an already published price, the old value, the new value and the detection time are stored. If the API fails, the last valid data is kept and its freshness is flagged. No premium/discount against the national reference is computed because Dehesa’s U.S. reference price is monthly (NASS) and not comparable with daily bids. “Near me”: the ZIP code is turned into a state using a local table (2000 Census ZCTAs, state only); it is processed in your browser and neither stored nor sent. Organic premium (corn, soybean and wheat pages): median organic bid from USDA AMS 3802 minus the median conventional bid with the same specification (commodity, class, grade, elevator and bid type) on the same date; shown only with at least 3 organic and 5 conventional series. Indicative only: two different reports whose regional coverage and delivery month may differ.'] },
        { h: 'U.S. exports', id: 'exportaciones', p: ['Weekly export sales come from USDA FAS’s Export Sales Reporting (FAS open API), released on Thursdays and covering wheat, corn, sorghum, barley, soybeans and products, cotton, rice, beef and pork. Figures are metric tons (cotton in bales) reported by companies to USDA: “exported” is accumulated shipments in the marketing year, “outstanding sales” are sales already made but not shipped, and “total commitment” is their sum. Totals add up the published destinations and the EU aggregate counts as one destination. Monthly trade by country comes from USDA FAS GATS, using U.S. Census Bureau data: only U.S. trade with each country (not flows between third countries), in current dollars and, where the Census measures in kilograms, in tonnes; the main agricultural partners are included, not every country. Product groups are built from tariff (HS) chapters and are approximate. The last two months may be revised. Public U.S. Government data; not converted or compared with prices.'] },
        { h: 'Product page', id: 'producto', p: ['The product page (wheat, corn, soybeans, rice, beef, pork, milk and chicken) creates no new data: it gathers on one page what each block already publishes, with its source and unit (prices, supply and demand, export sales, trade by country, crop or livestock inventories, drought and costs). Markets are neither converted nor added together: the U.S. beef and pork price is live weight and is not equivalent to the European carcass price. The production-weighted drought average is a Dehesa calculation over the 5 largest producing states and expresses the share of each state\'s area in moderate drought or worse, not of the cropped area. A block with no data does not appear. For soybeans, the price shown is soybean meal, not the beans.'] },
        { h: 'EU prices', id: 'europa', p: ['The EU prices page gathers every price series that the European Commission publishes in its Agri-food Data Portal (public API): cereals, oilseeds and meals, dairy, beef, pigmeat, poultry, eggs, lamb, rice, raw milk, olive oil, sugar, wine and fertilisers, country by country. Each line is the price the portal publishes, in its own unit (€/t, €/100 kg, €/hl…), not converted and with no markets averaged; when a country publishes several markets, each is shown separately, and rows that are not in euros are dropped. “EU” is an aggregate calculated by the Commission, not by Dehesa Index. The portal does not publish the date each figure is released, nor every country every week, so some countries have gaps. It is updated on Thursdays; history goes back to 2015 for most families (2021 for cereals and beef) and, for sugar, wine and fertilisers, as far as the source publishes.'] },
        { h: 'U.S. Drought Monitor', id: 'sequia', p: ['The share of each state in drought comes from the U.S. Drought Monitor, produced by the National Drought Mitigation Center (University of Nebraska-Lincoln) with USDA and NOAA. It is released on Thursdays with the map valid the previous Tuesday. Categories D0–D4 are shown as published by the API (cumulative: D1 includes D2, D3 and D4); changes are computed by subtracting percentages (percentage points) against the previous week and 52 weeks earlier. It is an assessment, not a forecast.'] },
        { h: 'U.S. livestock and dairy', id: 'ganaderia', p: ['Hog and cattle inventories, milk production by state and cold-storage stocks come from USDA NASS (Quick Stats: Hogs and Pigs, Cattle, Milk Production and Cold Storage) and are shown as published, in their original unit. Hog surveys are quarterly, cattle inventories semi-annual, and milk and cold storage monthly. State data are shown only when NASS publishes them for the same period. Changes are simple percentage changes between two published figures.'] },
        { h: 'U.S. farm input costs', id: 'insumos', p: ['Prices-paid indexes for farmers (fertilizer, fuel, feed, agrochemicals, seed, machinery, services, wages, rent and interest) come from USDA NASS, Agricultural Prices (Quick Stats), with 2011 = 100. NASS no longer publishes absolute fertilizer or fuel prices, so the official indexes are shown; no per-tonne or per-litre prices are estimated. Changes are percentage changes between published indexes.'] },
        { h: 'U.S. food prices, costs and farm income', id: 'costes', p: ['Food prices (CPI and PPI forecasts), costs and returns by crop and livestock, cost forecasts and farm income come from official USDA Economic Research Service files (Food Price Outlook, Commodity Costs and Returns, Cost of Production Forecasts and Farm Income and Wealth Statistics). They are shown as published; the latest farm-income year and the price and cost forecasts are ERS forecasts. The per-unit break-even is computed by Dehesa as total cost per acre divided by yield per acre, and is labelled as such on the page.'] },
        { h: 'U.S. yields and acreage by state', id: 'rendimientos', p: ['Yield per acre, planted and harvested area and production by state come from USDA NASS (Quick Stats, Crop Production and Acreage surveys), in their original units (acres, bushels, pounds). County figures (NASS county estimates via Quick Stats, refreshed monthly) exist only for the crops and counties NASS publishes; coverage changes every year and counties without a figure are shown in grey, never as zero. “Other counties” is the sum NASS does not break out. Boundaries are from the U.S. Census (public domain, via us-atlas). The latest year may be a NASS estimate or forecast until the crop year closes; states without a published figure are not filled in.'] },
        { h: 'Manitoba: cattle, sheep, goats and hogs', id: 'manitoba', p: ['Prices at Manitoba cattle, sheep and goat auctions and hog prices from Manitoba processors come from Manitoba Agriculture\'s weekly reports (PDF), under the OpenMB licence (attribution required). Each report is read by a parser that refuses to publish what does not add up: head counts that do not sum, low, average and high out of order, impossible dates, prices out of range. Manitoba reported goats per head and since April 2025 converts them to C$/cwt using average weights it estimates itself; they are accepted only when the report labels them that way. If two reports give different figures for the same sale, the cell is left empty (a gap, never a zero). Changes always compare the same series with its dates; Canfax\'s monthly history is not used.'] },
        { h: 'Supply and demand', id: 'oferta-demanda', p: ['Production, consumption, trade and stock balances come from the USDA Foreign Agricultural Service (PSD Online, CC BY 4.0 licence) and are updated with the monthly WASDE report. The year shown (2025) is the marketing year that starts that year (2025/26); the latest one is a forecast USDA revises every month. "World" is the sum of the countries in the PSD database, counting the EU once; it is not a figure published by USDA. Marketing years differ between countries, and exports and imports are reported separately, so world trade does not always balance. Figures are in thousand tonnes (meat in carcass-weight equivalent). Without PSD data, nothing is drawn.'] },
        { h: 'Dehesa Index: the composite index', id: 'indice', p: ['A monthly index with base 100 in October 2024, for the EU market (weights below). The US has its own index, with the same base and method, built from USDA NASS, USDA AMS and EIA; it has no fertiliser group (there is no verified series) and rescales the other weights; it uses WTI instead of Brent and has no lamb. Canada has one too, with farm-gate prices from Statistics Canada in Canadian dollars; it has no feed, fertiliser or energy group (there are no verified series with enough history), rescales the other weights, and its last month is the latest with data for every series, because Statistics Canada publishes about two months late. Each verified series is converted to a monthly average and rebased to 100; each group is the simple mean of its series; the index is the weighted mean of the groups: Cereals 25%, Livestock 25%, Dairy 15%, Feed 15%, Fertilisers 10%, Energy 10%.', 'Because each series is rebased in its own unit, the index measures evolution, is not a price and does not mix currencies. If a series has a month missing at the source, the previous month is carried forward and declared in the data file. The UK will be added once it has at least 24 months of history. The “Build your own index” panel lets you change the weights and compare them with the official index.'] },
        { h: 'Limitations', ul: [
          { t: 'These are not real-time prices: frequency is set by each source (weekly, monthly or quarterly).' },
          { t: 'U.S. prices (NASS) are farm-gate and EU prices are market prices; even shown in the same currency, they are not always the same concept.' },
          { t: 'Sources may revise their data or change definitions; we show the latest published version.' },
          { t: 'Nothing here is financial or investment advice.' }
        ] },
        { h: 'Open data and corrections', p: ['The files behind the dashboard are published in the site’s data folder (JSON and CSV), with the source and methodology of each series. If you spot an error or a definition that could be better, write to hola@dehesaindex.com.'] }
      ],
      links: [{ href: 'clima.html', t: 'Agricultural climate' }, { href: 'data/', t: 'Open data' }, { href: 'legal.html', t: 'Legal notice & privacy' }, { href: 'informacion.html', t: 'Information' }]
    },
    fr: {
      title: 'Méthodologie',
      sub: 'Comment les données sont vérifiées, datées et converties, et comment l’indice composite est calculé.',
      sections: [
        { h: 'Principe : uniquement des données vérifiables', p: ['Chaque chiffre du tableau de bord provient d’une source officielle ou ouverte, avec sa date et un lien pour le vérifier. Sans série traçable, aucune valeur n’est affichée : nous ne comblons pas les trous avec des estimations ni des données fictives.'] },
        { h: 'Signification des étiquettes', id: 'etiquettes', ul: [
          { b: 'DONNÉE OFFICIELLE.', t: 'Donnée vérifiée à sa source officielle, avec date d’observation et de publication.' },
          { b: 'NON COMPARABLE.', t: 'La donnée est réelle, mais sa définition n’équivaut pas à celle de l’autre marché. Exemples : les prix américains du porc, du bovin et du poulet sont en poids vif, contre le poids carcasse dans l’UE ; les engrais de l’UE sont des indices agrégés d’éléments nutritifs. Elle est affichée avec l’étiquette et exclue des comparaisons directes.' },
          { b: 'EN ATTENTE.', t: 'Il n’existe pas encore de source vérifiable et correctement licenciée. La fiche n’affiche aucun chiffre tant qu’il n’y en a pas.' }
        ] },
        { h: 'Sources et fréquence', ul: [
          { b: 'États-Unis — USDA NASS (Quick Stats).', t: 'Prix reçu par l’agriculteur, mensuel et national : blé, maïs, riz, lait, œufs, porc, bovin et poulet. NASS publie une fois par mois ; nous consultons chaque semaine pour ne manquer aucune publication.' },
          { b: 'UE — Commission européenne, Agri-food Data Portal.', t: 'Prix de marché hebdomadaires avec l’Espagne comme référence (porc, bœuf, agneau, poulet, œufs, céréales, huile d’olive, sucre, lait, tourteau de soja, engrais). Les coefficients par pays sont calculés avec des données réelles de la même semaine.' },
          { b: 'Royaume-Uni — Defra (Open Government Licence v3.0).', t: 'Lait et indices des prix agricoles, mensuels. Les prix hebdomadaires britanniques des céréales et du bétail sont publiés par l’AHDB à des conditions qui interdisent l’usage automatisé ; ces fiches restent donc en attente.' },
          { b: 'Canada — Statistique Canada (Licence du gouvernement ouvert – Canada).', t: 'Prix mensuels payés aux producteurs (tableau 32-10-0077-01) : blé, orge, avoine, canola, maïs, lait, bovins, porcs, agneaux, poulet et œufs. Le tableau ne donne que les provinces, sans total national ; chaque produit utilise une province de référence (Saskatchewan, Alberta, Ontario ou Québec, indiquée sur la fiche). Devise CAD ; lait converti de $/kilolitre en $/100 kg avec 1,03 kg/l. Comparabilité directionnelle avec les États-Unis.' },
          { b: 'Canada — Alberta Agriculture and Irrigation (Open Government Licence – Alberta).', t: 'Revues hebdomadaires des marchés des cultures et du bétail (PDF au format fixe) : offres d’élévateur pour le canola, le blé CWRS, le blé, l’orge et l’avoine fourragers, offres au comptant pour la lentille Laird et le pois vert, bouvillons en vente directe et porcs au comptant (indice 100, par kg de carcasse). Ce sont des prix offerts par des acheteurs, pas des transactions conclues ; ils sont datés par rapport (vendredi). Ils ne remplacent pas les prix mensuels de Statistique Canada, dont la base est différente.' },
          { b: 'Danemark — Statistics Denmark (CC BY 4.0).', t: 'Prix mensuels à la ferme (tableau LPRIS10, depuis 2005) et lait à la ferme (ANI71, depuis 1995) en couronnes danoises (DKK), convertis en euros au taux de la BCE. Blé, orge, avoine, seigle, colza, lait, porcs, jeunes bovins et poulets. Comparabilité directionnelle : définitions et qualités danoises, non identiques aux prix européens de référence.' },
          { b: 'Pays-Bas et Australie — CBS et ABS (CC BY 4.0).', t: 'Pas de prix à la ferme publiés : uniquement production, cultures, abattages et exportations (page Production par pays), tels que publiés par la source.' },
          { b: 'Eurostat.', t: 'Indices des prix agricoles de l’UE, trimestriels.' },
          { b: 'Eurostat — Comext (commerce extérieur).', t: 'Base DS-045409 (commerce de l’UE depuis 1988 par chapitre du Système harmonisé), API Comext. Huit pays déclarants (ES, FR, DE, BE, AT, PT, DK, NL). Total agroalimentaire = somme des chapitres 01 à 24 ; séries propres pour animaux vivants, viande, produits laitiers, légumes, fruits, céréales, oléagineux, graisses, sucre, boissons, aliments pour animaux et engrais (31), plus huile d’olive (1509) et liège (45) le cas échéant. Mensuel depuis 2000 avec le partenaire « monde » (y compris le commerce intra-UE), avec le total aussi séparé en intra- et extra-UE. Partenaires : classement des 10 premiers de la dernière année complète, par pays et par flux, avec une série annuelle depuis 2002 ; le produit par partenaire couvre les 6 dernières années complètes. Valeurs en millions d’euros telles que publiées par Eurostat, non ajustées. Le dernier mois et la dernière année sont révisés. Aux Pays-Bas et en Belgique, une part importante est du transit et de la réexportation. Mise à jour les 16, 18 et 22 de chaque mois.' },
          { b: 'USITC — Tarif harmonisé (HTS).', t: 'API REST de l’USITC, édition en vigueur. Chapitres 01-24 et 31 ; une ligne par code à 8 chiffres avec taux général (NPF), préférences, colonne 2 et unités des lignes statistiques. Les moyennes ad valorem sont simples (non pondérées). Les contingents et les droits par décret ne figurent pas dans le tableau de base : ils sont résumés dans une couche manuelle datée.' },
          { b: 'ASFC, SNICE et TARIC — droits à l’importation.', t: 'Mexique : lignes du tarif LIGIE (Excel SNICE, droit général). Canada : base du Tarif des douanes de l’ASFC (NPF et préférences ACEUM, AECG, PTPGP… ; les lignes « within/over access commitment » sont signalées comme contingent). UE : mesures d’importation du TARIC (droit de pays tiers erga omnes, préférences de certains partenaires et existence de contingent). Même schéma que les États-Unis ; chapitres 01-24 et 31 ; moyennes ad valorem simples non pondérées. Dans l’UE « cond. » = droit conditionnel. Les mesures récentes de l’UE (Russie et Biélorussie, Ukraine, Mercosur) figurent dans une couche manuelle datée, vérifiée auprès d’EUR-Lex, d’Access2Markets et du Conseil de l’UE.' },
          { b: 'Banque mondiale — indicateurs macro.', t: 'Indicateurs NY.GDP.MKTP.CD, NY.GDP.PCAP.CD, SP.POP.TOTL, SL.UEM.TOTL.ZS et NV.AGR.TOTL.ZS (dernière année disponible). Dette brute des administrations publiques (% du PIB) d’Eurostat gov_10dd_edpt1 ; pour le Canada et l’Australie, dette de l’administration centrale de la Banque mondiale (non comparable). Mise à jour mensuelle.' },
          { b: 'Canada — Statistique Canada (statistiques élargies, Licence ouverte de Statistique Canada).', t: 'Cultures (32-10-0359), stocks (32-10-0007 et 32-10-0480), livraisons et broyage (32-10-0351, 32-10-0352), élevage, lait, œufs et volailles, recettes et revenu agricoles (32-10-0045, 32-10-0046, 32-10-0052), indices de prix (32-10-0098, 18-10-0258), engrais (32-10-0038) et commerce extérieur (12-10-0163 par produit, 12-10-0011 et 12-10-0173 par partenaire, 12-10-0175 par province et partenaire depuis 2018), bilan des grains en fin de campagne (32-10-0013 ; la période est l’année de récolte) et bovins et veaux (32-10-0125). Valeurs converties de l’unité d’origine en millions de CAD, milliers de tonnes ou têtes ; commerce sur base douanière, non désaisonnalisé. Le classement des partenaires est recalculé à chaque exécution. Lundi et jeudi.' },
          { b: 'Espagne — MAPA (enquêtes sur l’élevage).', t: 'Effectifs de bovins, ovins, caprins et porcins (ibériques et non ibériques) par province, recensements de mai et novembre depuis 2010, lus dans le classeur efectivos_ganado.xlsx publié par le MAPA. Conservés tels quels (à une décimale) ; une valeur négative de la source reste un manque et les lignes de communauté autonome sont ignorées. Réutilisation avec mention de la source. Hebdomadaire (jeudi).' },
          { b: 'Espagne — MAPA (bilans de céréales).', t: 'Bilan annuel du blé tendre et dur, de l’orge, du maïs, du seigle, de l’avoine, du sorgho et du triticale par campagne (1er juil.-30 juin) depuis 2016/17 : surface, rendement, production, stocks, importations, consommation intérieure et exportations, lus dans les PDF du MAPA. Chiffres tels que publiés ; cellules vides = pas de donnée ; le statut (estimation, provisoire) est celui du PDF et les écarts de sa colonne Total sont signalés. Réutilisation avec mention de la source. Hebdomadaire (jeudi).' },
          { b: 'Espagne — MAPA (bilans du secteur oléicole et prévision de récolte).', t: 'Bilan de l’huile d’olive, de l’huile de grignons (campagne 1er oct-30 sept) et des olives de table (1er sept-31 août) depuis 2020/21 : stocks, production, importations, marché intérieur, exportations, ajustements et pertes, lus dans les PDF du MAPA, avec la ventilation UE-27 / hors UE lorsqu’elle est publiée. Plus la prévision de récolte d’huile d’olive par communauté autonome (estimation publiée le 1er octobre), toujours présentée comme estimation. Chiffres tels que publiés ; stocks / sorties est un calcul de Dehesa Index et il est indiqué. Réutilisation avec mention de la source. Hebdomadaire (jeudi).' },
          { b: 'Espagne — MAPA (lait cru, INFOLAC).', t: 'Livraisons mensuelles de lait cru aux premiers acheteurs (t), prix moyen déclaré (€/l, moyenne pondérée hors TVA et transport), matière grasse et protéines (%), éleveurs et acheteurs, national et par communauté autonome, lus dans le rapport mensuel du MAPA (déclarations obligatoires, RD 319/2015). Chaque rapport couvre 12 mois et le fichier accumule l’historique (prix depuis janvier 2022, livraisons depuis septembre 2024) ; le MAPA précise que les données ne sont pas consolidées : un rapport ultérieur peut réviser des mois et le dernier prévaut. Mois sans donnée = manque, jamais zéro. Réutilisation avec mention de la source. Hebdomadaire (jeudi).' },
          { b: 'Espagne — MAPA (abattages de bétail).', t: 'Têtes abattues et tonnes de poids carcasse par espèce (bovins, ovins, caprins, porcins, équidés, volailles et lapins), chaque mois, national depuis 2022 et par communauté autonome depuis 2025, lus dans le classeur mensuel de l’enquête sur les abattages du MAPA. Volailles et lapins sont publiés en milliers de têtes. Le poids carcasse moyen est notre propre calcul (t divisées par les têtes). Le confidentiel (DC) est un manque, jamais zéro. En août 2026 la ligne Total des feuilles mensuelles ne correspond pas à la série nationale : on utilise la nationale et l’écart est consigné. Données provisoires ; le dernier classeur prévaut. Réutilisation avec mention de la source. Hebdomadaire (jeudi).' },
          { b: 'Espagne — MAPA (abattages par province).', t: 'Têtes abattues et tonnes de poids carcasse par espèce et par province, chaque année de 2004 à 2025, lues dans les classeurs annuels de l’enquête sur les abattages en abattoirs (feuilles têtes et viande ; .xls jusqu’en 2022 et .xlsx depuis 2023). Elles sont attribuées à la province de l’abattoir, non à celle d’élevage. Volailles et lapins sont en milliers de têtes jusqu’en 2024 et en têtes depuis 2025 : ici tout en têtes. Le confidentiel (DC) est un manque, jamais zéro, non estimé par soustraction bien que le total de la communauté l’inclue. « Espagne » est la ligne publiée, qui additionne les provinces et les autres abattages sans province (importants pour ovins et caprins jusqu’en 2007). Jusqu’en 2013 le classeur ne précise pas recensement ou échantillon et 2007, 2012, 2013 et 2015 indiquent « données non élevées » ; depuis 2016 il s’agit d’un recensement. Le total national de 2022 à 2025 coïncide avec la série mensuelle. Réutilisation avec mention de la source. Hebdomadaire (jeudi).' },
          { b: 'Espagne — MAPA (vin, INFOVI).', t: 'Raisin reçu (t), production de vin par catégorie (AOP, IGP, cépage, sans indication géographique) et couleur, sorties (exportations déclarées et intérieures) et stocks de vin et de moût au 31 juillet (hl), par campagne (1er août–31 juillet) et communauté, lus dans le rapport élargi de juillet de l’INFOVI du MAPA (depuis la campagne 2020/21). Ce sont des déclarations des caves, pas un bilan sectoriel ; le MAPA donne les exportations à titre indicatif. Un nouveau rapport remplace celui de sa campagne et les révisions sont consignées. Un manque est un manque, jamais zéro. Réutilisation avec mention de la source. Hebdomadaire (jeudi).' },
          { b: 'Espagne — MAPA (vin mensuel, INFOVI).', t: 'Stocks initiaux et finaux de vin et de moût, production du mois, entrées et sorties par destination (intérieur, UE et pays tiers) en hl, par mois (depuis janvier 2021) et communauté, lus dans le rapport mensuel de l’INFOVI du MAPA. Périmètre plus étroit que celui de la campagne (opérateurs déclarant chaque mois), donc on ne les mélange pas. Le mois est lu dans le titre de chaque classeur, car les noms de fichier ne sont pas fixes. Un mois sans classeur est un manque ; un tableau absent, pas de donnée (jamais zéro). Les écarts de 0,2–1 % entre la clôture d’un mois et l’ouverture du suivant sont des révisions du MAPA et sont signalés. Réutilisation avec mention de la source. Hebdomadaire (jeudi).' },
          { b: 'Espagne — MAPA (bilan du vin, historique).', t: 'Bilan officiel du vin des campagnes 2009/10 à 2015/16 en milliers d’hl : stocks, production, importations, exportations, utilisation intérieure et stocks finaux, national, d’après les classeurs du MAPA. Les cellules vides sont des manques, jamais zéro ; le définitif remplace le provisoire (2015/16 est provisoire). Pas de ventilation par région ni de bilan de 2016/17 à 2019/20, et il n’est pas comparable aux déclarations INFOVI.' },
          { b: 'Énergie et engrais.', t: 'Diesel américain (EIA, hebdomadaire) et de l’UE (Oil Bulletin, hebdomadaire) ; gaz naturel (EIA hebdomadaire ; Banque mondiale mensuel), pétrole WTI et Brent (EIA, hebdomadaire) ; urée (Banque mondiale, mensuelle).' },
          { b: 'Climat — NASA POWER.', t: 'Pluie et température mensuelles (réanalyse MERRA-2) en 31 points représentatifs de régions productrices, comparées à la moyenne 2001-2020 du même mois, avec un historique mensuel depuis 2000. Les mois les plus récents sont calculés par la NASA avec un autre flux de traitement (GEOS-IT), susceptible d’être révisé. C’est un contexte climatique (une maille d’environ 50 km, pas une station ni la région entière) ; il ne prévoit ni récoltes ni prix.' },
          { b: 'Offre et demande — USDA PSD.', t: 'Bilans par pays et par campagne des céréales, oléagineux, viandes, lait et sucre (licence CC BY 4.0), mensuels avec le WASDE.' },
          { b: 'Tourteau de soja des États-Unis — USDA AMS.', t: 'Prix hebdomadaire du tourteau de soja (Iowa, FOB, 46,5-48 % de protéines) du rapport 3511 d’USDA AMS Market News, en tonne courte. C’est un marché régional, pas un contrat à terme ; la comparaison avec l’Europe est indicative.' },
          { b: 'Taux de change.', t: 'Taux de référence de la Banque centrale européenne, chaque jour ouvré.' }
        ] },
        { h: 'Dates : observation et publication', p: ['Chaque donnée porte deux dates : l’observation (la période concernée) et la publication (quand la source l’a diffusée). Certaines sources n’indiquent pas de date de publication ; nous enregistrons alors le jour où nous avons collecté la donnée pour la première fois et l’indiquons sur la fiche.'] },
        { h: 'Devises et unités', p: ['Les données sont conservées dans la devise et l’unité de la source. Pour les comparer, le tableau de bord les convertit avec le taux de référence de la BCE du dernier jour ouvré et des facteurs d’unité fixes et visibles (par exemple, 1 douzaine d’œufs = 0,6804 kg). Une conversion ne rend pas comparable une donnée qui ne l’est pas.'] },
        { h: 'Taux d’intérêt, devises et provenance', p: ["Les taux directeurs des États-Unis, de la zone euro, du Canada et de l’Australie proviennent des banques centrales : BCE (facilité de dépôt), Banque du Canada (API Valet) et Reserve Bank of Australia (tableau F1.1) ; celui des États-Unis (taux des fonds fédéraux) arrive via le jeu WS_CBPOL de la Banque des règlements internationaux (BRI), qui reprend la série de la Réserve fédérale. La conversion en euros utilise les moyennes mensuelles historiques de la BCE (USD, CAD, AUD, GBP et DKK depuis 1999) : chaque valeur est convertie à la moyenne de son propre mois et signalée comme conversion, jamais comme donnée de la source."] },
        { h: "Reproductibilité, révisions et couverture", p: ["Chaque série porte sa filiation (fichier, flux de mise à jour et dernière exécution, visibles sur la page d’état). Les changements dans des périodes déjà publiées sont détectés et conservés (data/revisions.json) ; ce peut être des révisions de la source, des corrections ou des réajustements de l’historique, et la source ne le confirme pas, et l’historique git permet de reconstituer ce que le site affichait à une date donnée (script reconstruct-indicator). Le Coverage Score de chaque pays mesure quelles catégories ont des données, combien sont à jour et combien de périodes elles couvrent. Quand une même série provient de plusieurs sources, la plus prioritaire est affichée (nationale, puis Eurostat, internationale, secondaire) et les autres sont enregistrées, sans doublon."] },
        { h: 'État des cultures', id: 'cultivos', p: ['Ces données viennent du rapport hebdomadaire Crop Progress de l’USDA NASS (API Quick Stats), publié le lundi après-midi, heure américaine, environ d’avril à novembre (le blé d’hiver est aussi noté à l’automne). La notation est la part de la surface dans chaque catégorie — très mauvais, mauvais, moyen, bon, excellent — ; « bon + excellent » est la somme des deux dernières. Elle est donnée par des correspondants locaux du NASS : elle est donc subjective et ne constitue pas une prévision de récolte ni de prix. L’avancement est la part de la surface ayant atteint chaque stade (semé, récolté...). La moyenne 5 ans et la comparaison avec l’an dernier sont un calcul propre à Dehesa Index : on prend la même date dans les campagnes précédentes, par interpolation entre rapports hebdomadaires, et seulement si au moins 4 des 5 campagnes ont une donnée. Un stade terminé (100 %) reste à 100 % les semaines suivantes. Les valeurs que le NASS ne publie pas ne sont pas complétées.'] },
        { h: 'Marchés USDA', id: 'mercados', p: ['Prix de marché américains tels que publiés par USDA AMS Market News (API MARS) : aliments et sous-produits, éthanol et coproduits, céréales, oléagineux, légumineuses, riz, volaille, œufs, viande et sous-produits, porcelets, bétail en vente directe, foin et produits laitiers. Ils sont lus chaque jour ouvré (certains rapports sont hebdomadaires). Chaque série est une combinaison fixe de produit, qualité, lieu et unité du rapport lui-même ; si un même jour ou une même semaine porte deux chiffres différents pour la même série, ce point est écarté plutôt que deviné. Les devises et les unités ne sont pas converties. Quand un rapport donne un prix moyen, il est affiché ; quand il ne donne que minimum et maximum, le milieu est affiché, signalé par ≈. Les données sont officielles mais ne constituent pas un indicateur de Dehesa Index et ne sont pas comparables aux données européennes : chaque rapport a sa propre base de lieu, qualité et livraison.'] },
        { h: 'Prix locaux des grains (É.-U.)', id: 'precios-locales', p: ['Les offres d’achat au comptant (cash bids) viennent des rapports céréales de l’USDA AMS Market News (API MARS), lus en CI ; la clé d’API n’atteint jamais le navigateur. Chaque prix indique ce qu’il représente : une région de l’État, un terminal, un marché d’exportation ou l’État entier. Dehesa Index ne présente pas un chiffre comme « silo local » sauf si le rapport identifie le silo, et ne place aucun point sur la carte sans localisation réelle. Chaque série est une combinaison fixe de produit, classe de blé, qualité, type d’acheteur, période de livraison et unité ; HRW, SRW, HRS et dur ne sont jamais mélangés. La moyenne est affichée quand le rapport la donne, le prix exact si minimum et maximum coïncident, sinon la fourchette ; jamais un milieu calculé. La base n’apparaît que si l’USDA la publie et n’est jamais calculée. La variation n’est calculée qu’entre observations consécutives proches (7 jours pour les rapports quotidiens, 14 pour les hebdomadaires). Si l’USDA corrige un prix déjà publié, l’ancienne valeur, la nouvelle et la date de détection sont conservées. Si l’API échoue, la dernière donnée valide est conservée et sa fraîcheur signalée. Aucune prime/décote par rapport à la référence nationale n’est calculée : la référence américaine de Dehesa est mensuelle (NASS) et n’est pas comparable à des offres quotidiennes. « Près de moi » : le code postal est converti en État grâce à une table locale (ZCTA du recensement 2000, État seulement) ; il est traité dans votre navigateur et n’est ni conservé ni envoyé. Prime bio (fiches maïs, soja et blé) : médiane des offres bio USDA AMS 3802 moins médiane des offres conventionnelles de même spécification (produit, classe, qualité, silo et type d’offre) à la même date ; affichée seulement avec au moins 3 séries bio et 5 conventionnelles. Indicatif : deux rapports distincts dont la couverture régionale et le mois de livraison peuvent différer.'] },
        { h: 'Exportations américaines', id: 'exportaciones', p: ['Les ventes à l’exportation hebdomadaires viennent du rapport Export Sales Reporting de l’USDA FAS (API ouverte de la FAS), publié le jeudi, qui couvre le blé, le maïs, le sorgho, l’orge, le soja et ses dérivés, le coton, le riz, le bœuf et le porc. Les chiffres sont des tonnes métriques (coton en balles) déclarées par les entreprises à l’USDA : « exporté » correspond aux expéditions cumulées de la campagne, « ventes en attente » aux ventes conclues mais non expédiées, et « engagement total » à leur somme. Les totaux additionnent les destinations publiées et l’agrégat UE compte comme une seule destination. Le commerce mensuel par pays vient de l’USDA FAS GATS, à partir des données du Census Bureau : uniquement le commerce des États-Unis avec chaque pays (pas les flux entre pays tiers), en dollars courants et, lorsque le Census mesure en kilos, en tonnes ; les principaux partenaires agricoles sont inclus, pas tous les pays. Les groupes de produits reposent sur les chapitres tarifaires (SH) et sont approximatifs. Les deux derniers mois peuvent être révisés. Données publiques du gouvernement américain ; ni converties ni comparées aux prix.'] },
        { h: 'Fiche produit', id: 'producto', p: ['La fiche produit (blé, maïs, soja, riz, bœuf, porc, lait et poulet) ne crée pas de données nouvelles : elle réunit sur une page ce que publie déjà chaque bloc, avec sa source et son unité (prix, offre et demande, ventes à l’exportation, commerce par pays, culture ou effectifs de bétail, sécheresse et coûts). Les marchés ne sont ni convertis ni additionnés : le prix américain du bœuf et du porc est en poids vif et n’équivaut pas au prix en carcasse européen. La moyenne de sécheresse pondérée par la production est un calcul de Dehesa sur les 5 premiers États producteurs et exprime la part de la surface de l’État en sécheresse modérée ou pire, pas de la surface cultivée. Un bloc sans données n’apparaît pas. Pour le soja, le prix affiché est celui du tourteau, pas du grain.'] },
        { h: 'Prix de l’UE', id: 'europa', p: ['La page Prix de l’UE réunit toutes les séries de prix publiées par la Commission européenne dans son Agri-food Data Portal (API publique) : céréales, oléagineux et tourteaux, produits laitiers, bovins, porc, volaille, œufs, agneau, riz, lait cru, huile d’olive, sucre, vin et engrais, pays par pays. Chaque courbe est le prix publié par le portail, dans son unité (€/t, €/100 kg, €/hl…), sans conversion ni moyenne entre marchés ; si un pays publie plusieurs marchés, chacun est affiché séparément, et les lignes qui ne sont pas en euros sont écartées. « UE » est un agrégat calculé par la Commission, pas par Dehesa Index. Le portail ne publie pas la date de mise en ligne de chaque valeur, ni tous les pays chaque semaine : certains pays ont donc des trous. Mise à jour le jeudi ; l’historique remonte à 2015 pour la plupart des familles (2021 pour les céréales et les bovins) et, pour le sucre, le vin et les engrais, aussi loin que la source le publie.'] },
        { h: 'Moniteur de sécheresse américain', id: 'sequia', p: ['La part de chaque État en sécheresse vient du U.S. Drought Monitor, produit par le National Drought Mitigation Center (Université du Nebraska-Lincoln) avec l’USDA et la NOAA. Il est publié le jeudi avec la carte valable le mardi précédent. Les catégories D0–D4 sont affichées telles que publiées par l’API (cumulatives : D1 inclut D2, D3 et D4) ; les variations sont calculées en soustrayant les pourcentages (points de pourcentage) par rapport à la semaine précédente et à 52 semaines avant. C’est une évaluation, pas une prévision.'] },
        { h: 'Élevage et lait aux États-Unis', id: 'ganaderia', p: ['Les inventaires de porcs et de bovins, la production de lait par État et les stocks frigorifiques viennent de l’USDA NASS (Quick Stats : Hogs and Pigs, Cattle, Milk Production et Cold Storage) et sont présentés tels que publiés, dans leur unité d’origine. Les enquêtes porcines sont trimestrielles, celles des bovins semestrielles, et le lait et les stocks frigorifiques mensuels. Les données par État ne sont affichées que si NASS les publie pour la même période. Les variations sont de simples variations en pourcentage entre deux chiffres publiés.'] },
        { h: 'Coûts des intrants agricoles aux États-Unis', id: 'insumos', p: ['Les indices des prix payés par les agriculteurs (engrais, carburants, aliments du bétail, agrochimie, semences, machines, services, salaires, fermages et intérêts) viennent de l’USDA NASS, Agricultural Prices (Quick Stats), base 2011 = 100. NASS ne publie plus de prix absolus d’engrais ni de carburants ; on affiche donc les indices officiels, sans estimer de prix à la tonne ou au litre. Les variations sont des variations en pourcentage entre indices publiés.'] },
        { h: 'Prix alimentaires, coûts et revenu agricole aux États-Unis', id: 'costes', p: ['Les prix alimentaires (prévisions IPC et IPP), les coûts et rendements par culture et élevage, les prévisions de coûts et le revenu agricole viennent des fichiers officiels de l’USDA Economic Research Service (Food Price Outlook, Commodity Costs and Returns, Cost of Production Forecasts et Farm Income and Wealth Statistics). Ils sont présentés tels que publiés ; la dernière année de revenu agricole et les prévisions de prix et de coûts sont des prévisions de l’ERS. Le seuil de rentabilité par unité est calculé par Dehesa (coût total par acre divisé par le rendement par acre) et signalé comme tel sur la page.'] },
        { h: 'Rendements et surfaces par État américain', id: 'rendimientos', p: ['Le rendement par acre, les surfaces semées et récoltées et la production par État viennent de l’USDA NASS (Quick Stats, enquêtes Crop Production et Acreage), dans leurs unités d’origine (acres, bushels, livres). Les chiffres par comté (estimations de comté du NASS via Quick Stats, actualisées chaque mois) n’existent que pour les cultures et comtés que le NASS publie ; la couverture change chaque année et les comtés sans chiffre apparaissent en gris, jamais à zéro. « Autres comtés » est la somme que le NASS ne détaille pas. Les contours viennent du Census Bureau (domaine public, via us-atlas). La dernière année peut être une estimation ou prévision de NASS tant que la campagne n’est pas close ; les États sans chiffre publié ne sont pas complétés.'] },
        { h: 'Manitoba : bovins, ovins, caprins et porcs', id: 'manitoba', p: ['Les prix des encans de bovins, d\'ovins et de caprins et ceux des porcs des transformateurs du Manitoba proviennent des rapports hebdomadaires (PDF) de Manitoba Agriculture, sous licence OpenMB (attribution obligatoire). Chaque rapport est lu par un lecteur qui refuse de publier ce qui ne colle pas : têtes qui ne s\'additionnent pas, minimum, moyenne et maximum dans le désordre, dates impossibles, prix hors plage. Le Manitoba publiait les chèvres par tête et, depuis avril 2025, les convertit en $ CA/cwt avec des poids moyens qu\'il estime lui-même ; elles ne sont acceptées que si le rapport l\'indique. Si deux rapports donnent des chiffres différents pour la même vente, la cellule reste vide (un vide, jamais un zéro). Les variations comparent toujours la même série avec ses dates ; l\'historique mensuel de Canfax n\'est pas utilisé.'] },
        { h: 'Offre et demande', id: 'oferta-demanda', p: ['Les bilans de production, consommation, commerce et stocks proviennent de l’USDA Foreign Agricultural Service (PSD Online, licence CC BY 4.0) et sont mis à jour avec le rapport mensuel WASDE. La campagne indiquée (2025) est celle qui commence cette année-là (2025/26) ; la plus récente est une prévision que l’USDA révise chaque mois. « Monde » est la somme des pays de la base PSD, l’UE comptant une fois ; ce n’est pas un chiffre publié par l’USDA. Les campagnes diffèrent selon les pays, et exportations et importations sont déclarées séparément : le commerce mondial ne s’équilibre donc pas toujours. Chiffres en milliers de tonnes (viande en équivalent carcasse). Sans donnée PSD, rien n’est tracé.'] },
        { h: 'Dehesa Index : l’indice composite', id: 'indice', p: ['Un indice mensuel en base 100 en octobre 2024, pour le marché de l’UE (pondérations ci-dessous). Les États-Unis ont leur propre indice, de même base et méthode, construit avec USDA NASS, USDA AMS et EIA ; sans groupe engrais (aucune série vérifiée), les autres poids sont redimensionnés ; WTI au lieu du Brent et pas d’agneau. Le Canada a aussi le sien, avec les prix départ ferme de Statistique Canada en dollars canadiens ; sans groupes aliments du bétail, engrais ni énergie (aucune série vérifiée avec assez d’historique), les autres poids sont redimensionnés et son dernier mois est le dernier disposant de données pour toutes les séries, car Statistique Canada publie avec environ deux mois de retard. Chaque série vérifiée est convertie en moyenne mensuelle et rebasée à 100 ; chaque groupe est la moyenne simple de ses séries ; l’indice est la moyenne pondérée des groupes : Céréales 25 %, Élevage 25 %, Produits laitiers 15 %, Aliments 15 %, Engrais 10 %, Énergie 10 %.', 'Chaque série étant rebasée dans sa propre unité, l’indice mesure une évolution, n’est pas un prix et ne mélange pas les devises. Si une série manque un mois à la source, le mois précédent est reporté et déclaré dans le fichier de données. Le Royaume-Uni sera ajouté avec au moins 24 mois d’historique. Le panneau « Créez votre indice » permet de modifier les poids et de les comparer à l’indice officiel.'] },
        { h: 'Limites', ul: [
          { t: 'Ce ne sont pas des prix en temps réel : la fréquence dépend de chaque source (hebdomadaire, mensuelle ou trimestrielle).' },
          { t: 'Les prix américains (NASS) sont départ ferme et ceux de l’UE sont des prix de marché ; même affichés dans la même devise, ce n’est pas toujours le même concept.' },
          { t: 'Les sources peuvent réviser leurs données ou changer leurs définitions ; nous affichons la dernière version publiée.' },
          { t: 'Rien ici ne constitue un conseil financier ou d’investissement.' }
        ] },
        { h: 'Données ouvertes et corrections', p: ['Les fichiers à partir desquels le tableau de bord est construit sont publiés dans le dossier de données du site (JSON et CSV), avec la source et la méthodologie de chaque série. Si vous repérez une erreur ou une définition perfectible, écrivez à hola@dehesaindex.com.'] }
      ],
      links: [{ href: 'clima.html', t: 'Climat agricole' }, { href: 'data/', t: 'Données ouvertes' }, { href: 'legal.html', t: 'Mentions légales et confidentialité' }, { href: 'informacion.html', t: 'Informations' }]
    },
    it: {
      title: 'Metodologia',
      sub: 'Come i dati vengono verificati, datati e convertiti, e come si calcola l’indice composito.',
      sections: [
        { h: 'Principio: solo dati verificabili', p: ['Ogni cifra del pannello proviene da una fonte ufficiale o aperta, con la sua data e un link per verificarla. Se non c’è una serie tracciabile, non viene mostrato alcun valore: non riempiamo i vuoti con stime né con dati campione.'] },
        { h: 'Cosa significano le etichette', id: 'etichette', ul: [
          { b: 'DATO UFFICIALE.', t: 'Dato verificato alla fonte ufficiale, con data di osservazione e di pubblicazione.' },
          { b: 'NON COMPARABILE.', t: 'Il dato è reale, ma la sua definizione non equivale a quella dell’altro mercato. Esempi: i prezzi USA di suini, bovini e pollo sono a peso vivo, contro il peso della carcassa nell’UE; i fertilizzanti UE sono indici aggregati di nutrienti. Viene mostrato con l’etichetta ed escluso dai confronti diretti.' },
          { b: 'IN ATTESA.', t: 'Non esiste ancora una fonte verificabile e con licenza adeguata. La scheda non mostra alcuna cifra finché non c’è.' }
        ] },
        { h: 'Fonti e frequenza', ul: [
          { b: 'USA — USDA NASS (Quick Stats).', t: 'Prezzo ricevuto dall’agricoltore, mensile e nazionale: grano, mais, riso, latte, uova, suini, bovini e pollo. NASS pubblica una volta al mese; controlliamo ogni settimana per non perdere nessuna pubblicazione.' },
          { b: 'UE — Commissione europea, Agri-food Data Portal.', t: 'Prezzi di mercato settimanali con la Spagna come riferimento (maiale, manzo, agnello, pollo, uova, cereali, olio d’oliva, zucchero, latte, farina di soia, fertilizzanti). I coefficienti per paese sono calcolati con dati reali della stessa settimana.' },
          { b: 'Regno Unito — Defra (Open Government Licence v3.0).', t: 'Latte e indici dei prezzi agricoli, mensili. I prezzi settimanali britannici di cereali e bestiame sono pubblicati da AHDB con condizioni che vietano l’uso automatico; queste schede restano quindi in attesa.' },
          { b: 'Canada — Statistics Canada (Open Government Licence – Canada).', t: 'Prezzi mensili pagati ai produttori (tabella 32-10-0077-01): grano, orzo, avena, canola, mais, latte, bovini, suini, agnelli, pollo e uova. La tabella contiene solo le province, senza totale nazionale; ogni prodotto usa una provincia di riferimento (Saskatchewan, Alberta, Ontario o Quebec, indicata nella scheda). Valuta CAD; latte convertito da $/kilolitro a $/100 kg con 1,03 kg/l. Comparabilità direzionale con gli Stati Uniti.' },
          { b: 'Canada — Alberta Agriculture and Irrigation (Open Government Licence – Alberta).', t: 'Rassegne settimanali dei mercati di colture e bestiame (PDF a formato fisso): offerte di elevatore per canola, grano CWRS, grano, orzo e avena da foraggio, offerte a pronti per lenticchie Laird e piselli verdi, manzi in vendita diretta e suini a pronti (indice 100, per kg di carcassa). Sono prezzi offerti dagli acquirenti, non operazioni concluse; sono datati per rapporto (venerdì). Non sostituiscono i prezzi mensili di Statistics Canada, che hanno una base diversa.' },
          { b: 'Danimarca — Statistics Denmark (CC BY 4.0).', t: 'Prezzi mensili alla fattoria (tabella LPRIS10, dal 2005) e latte alla fattoria (ANI71, dal 1995) in corone danesi (DKK), convertiti in euro al cambio della BCE. Grano, orzo, avena, segale, colza, latte, suini, giovani tori e polli. Comparabilità direzionale: definizioni e qualità danesi, non identiche ai prezzi europei di riferimento.' },
          { b: 'Paesi Bassi e Australia — CBS e ABS (CC BY 4.0).', t: 'Nessun prezzo alla fattoria pubblicato: solo produzione, colture, macellazioni ed esportazioni (pagina Produzione per paese), come pubblicati dalla fonte.' },
          { b: 'Eurostat.', t: 'Indici dei prezzi agricoli dell’UE, trimestrali.' },
          { b: 'Eurostat — Comext (commercio estero).', t: 'Dataset DS-045409 (commercio UE dal 1988 per capitolo del Sistema armonizzato), API Comext. Otto paesi dichiaranti (ES, FR, DE, BE, AT, PT, DK, NL). Totale agroalimentare = somma dei capitoli da 01 a 24; serie proprie per animali vivi, carne, latticini, ortaggi, frutta, cereali, semi oleosi, grassi, zucchero, bevande, mangimi e fertilizzanti (31), più olio d’oliva (1509) e sughero (45) dove applicabile. Mensile dal 2000 con partner «mondo» (include il commercio intra-UE), con il totale diviso anche in intra- ed extra-UE. Partner: classifica dei 10 maggiori dell’ultimo anno completo, per paese e flusso, con serie annuale dal 2002; il prodotto per partner copre gli ultimi 6 anni completi. Valori in milioni di euro come pubblicati da Eurostat, non destagionalizzati. L’ultimo mese e l’ultimo anno vengono rivisti. Nei Paesi Bassi e in Belgio una quota rilevante è transito e riesportazione. Aggiornamento il 16, 18 e 22 di ogni mese.' },
          { b: 'USITC — Tariffa armonizzata (HTS).', t: 'API REST della USITC, edizione corrente. Capitoli 01-24 e 31; una riga per codice a 8 cifre con aliquota generale (NPF), preferenze, colonna 2 e unità delle linee statistiche. Le medie ad valorem sono semplici (non ponderate). Contingenti e dazi per ordine esecutivo non sono nella tabella di base: sono riassunti in un livello manuale datato.' },
          { b: 'CBSA, SNICE e TARIC — dazi all’importazione.', t: 'Messico: linee della tariffa LIGIE (Excel SNICE, dazio generale). Canada: database del Customs Tariff della CBSA (NPF e preferenze CUSMA, CETA, CPTPP…; le linee «within/over access commitment» sono segnalate come contingente). UE: misure all’importazione del TARIC (dazio di paese terzo erga omnes, preferenze di alcuni partner ed esistenza di contingente). Stesso schema degli USA; capitoli 01-24 e 31; medie ad valorem semplici non ponderate. Nell’UE «cond.» indica un dazio condizionato. Le misure recenti dell’UE (Russia e Bielorussia, Ucraina, Mercosur) sono in un livello manuale datato, verificato su EUR-Lex, Access2Markets e Consiglio dell’UE.' },
          { b: 'Banca mondiale — indicatori macro.', t: 'Indicatori NY.GDP.MKTP.CD, NY.GDP.PCAP.CD, SP.POP.TOTL, SL.UEM.TOTL.ZS e NV.AGR.TOTL.ZS (ultimo anno disponibile). Debito lordo delle amministrazioni pubbliche (% PIL) da Eurostat gov_10dd_edpt1; per Canada e Australia, debito dell’amministrazione centrale della Banca mondiale (non confrontabile). Aggiornamento mensile.' },
          { b: 'Canada — Statistics Canada (statistiche ampliate, Statistics Canada Open Licence).', t: 'Colture (32-10-0359), scorte (32-10-0007 e 32-10-0480), consegne e molitura (32-10-0351, 32-10-0352), zootecnia, latte, uova e pollame, ricavi e reddito agricolo (32-10-0045, 32-10-0046, 32-10-0052), indici dei prezzi (32-10-0098, 18-10-0258), fertilizzanti (32-10-0038) e commercio estero (12-10-0163 per prodotto, 12-10-0011 e 12-10-0173 per partner, 12-10-0175 per provincia e partner dal 2018), bilancio dei cereali a fine campagna (32-10-0013; il periodo è l’anno di raccolta) e bovini e vitelli (32-10-0125). Valori convertiti dall’unità di origine in milioni di CAD, migliaia di tonnellate o capi; commercio su base doganale, non destagionalizzato. La classifica dei partner viene ricalcolata a ogni esecuzione. Lunedì e giovedì.' },
          { b: 'Spagna — MAPA (indagini zootecniche).', t: 'Consistenze di bovini, ovini, caprini e suini (iberici e non iberici) per provincia, censimenti di maggio e novembre dal 2010, lette dalla cartella efectivos_ganado.xlsx pubblicata dal MAPA. Conservate come pubblicate (a un decimale); un valore negativo della fonte resta un vuoto e le righe di comunità autonoma sono ignorate. Riutilizzo citando la fonte. Settimanale (giovedì).' },
          { b: 'Spagna — MAPA (bilanci dei cereali).', t: 'Bilancio annuale di frumento tenero e duro, orzo, mais, segale, avena, sorgo e triticale per campagna (1° lug.-30 giu.) dal 2016/17: superficie, resa, produzione, scorte, importazioni, consumo interno ed esportazioni, letti dai PDF del MAPA. Dati come pubblicati; celle vuote = nessun dato; lo stato (stima, provvisorio) è quello del PDF e le discrepanze della sua colonna Totale sono segnalate. Riutilizzo citando la fonte. Settimanale (giovedì).' },
          { b: 'Spagna — MAPA (bilanci del settore oleicolo e previsione del raccolto).', t: 'Bilancio di olio d’oliva, olio di sansa (campagna 1° ott-30 set) e olive da tavola (1° set-31 ago) dal 2020/21: scorte, produzione, importazioni, mercato interno, esportazioni, rettifiche e perdite, letti dai PDF del MAPA, con la ripartizione UE-27 / extra UE quando pubblicata. Più la previsione del raccolto di olio d’oliva per comunità autonoma (stima pubblicata il 1° ottobre), sempre indicata come stima. Cifre come pubblicate; scorte / uscite è un calcolo di Dehesa Index ed è indicato. Riutilizzo con citazione della fonte. Settimanale (giovedì).' },
          { b: 'Spagna — MAPA (latte crudo, INFOLAC).', t: 'Consegne mensili di latte crudo ai primi acquirenti (t), prezzo medio dichiarato (€/l, media ponderata esclusi IVA e trasporto), grasso e proteine (%), allevatori e acquirenti, nazionale e per comunità autonoma, letti dal rapporto mensile del MAPA (dichiarazioni obbligatorie, RD 319/2015). Ogni rapporto copre 12 mesi e il file accumula lo storico (prezzo da gennaio 2022, consegne da settembre 2024); il MAPA avverte che i dati non sono consolidati: un rapporto successivo può rivedere dei mesi e prevale l’ultimo. Mesi senza dato = vuoto, mai zero. Riutilizzo con citazione della fonte. Settimanale (giovedì).' },
          { b: 'Spagna — MAPA (macellazioni di bestiame).', t: 'Capi macellati e tonnellate di peso carcassa per specie (bovini, ovini, caprini, suini, equini, pollame e conigli), ogni mese, nazionale dal 2022 e per comunità autonoma dal 2025, letti dalla cartella mensile dell’indagine sulle macellazioni del MAPA. Pollame e conigli sono pubblicati in migliaia di capi. Il peso medio della carcassa è un nostro calcolo (t diviso capi). Il riservato (DC) è un vuoto, mai zero. Ad agosto 2026 la riga Total dei fogli mensili non coincide con la serie nazionale: si usa la nazionale e la differenza è annotata. Dati provvisori; prevale l’ultima cartella. Riutilizzo con citazione della fonte. Settimanale (giovedì).' },
          { b: 'Spagna — MAPA (macellazioni per provincia).', t: 'Capi macellati e tonnellate di peso carcassa per specie e provincia, ogni anno dal 2004 al 2025, letti dalle cartelle annuali dell’indagine sulle macellazioni nei macelli (fogli capi e carne; .xls fino al 2022 e .xlsx dal 2023). Sono attribuiti alla provincia del macello, non a quella di allevamento. Pollame e conigli sono in migliaia di capi fino al 2024 e in capi dal 2025: qui tutto in capi. Il riservato (DC) è un vuoto, mai zero, non stimato per sottrazione benché il totale della comunità lo includa. «Spagna» è la riga pubblicata, che somma le province e le altre macellazioni senza provincia (grandi per ovini e caprini fino al 2007). Fino al 2013 la cartella non precisa censimento o campione e 2007, 2012, 2013 e 2015 indicano «dati non elevati»; dal 2016 è censuaria. Il totale nazionale dal 2022 al 2025 coincide con la serie mensile. Riutilizzo con citazione della fonte. Settimanale (giovedì).' },
          { b: 'Spagna — MAPA (vino, INFOVI).', t: 'Uva ricevuta (t), produzione di vino per categoria (DOP, IGP, varietale, senza indicazione geografica) e colore, uscite (esportazioni dichiarate e interne) e scorte di vino e mosto al 31 luglio (hl), per campagna (1° ago–31 lug) e comunità, letti dal rapporto ampliato di luglio dell’INFOVI del MAPA (dalla campagna 2020/21). Sono dichiarazioni delle cantine, non un bilancio del settore; il MAPA indica le esportazioni come orientative. Un nuovo rapporto sostituisce quello della sua campagna e le revisioni sono annotate. Un vuoto è un vuoto, mai zero. Riutilizzo con citazione della fonte. Settimanale (giovedì).' },
          { b: 'Spagna — MAPA (vino mensile, INFOVI).', t: 'Scorte iniziali e finali di vino e mosto, produzione del mese, entrate e uscite per destinazione (interne, UE e paesi terzi) in hl, per mese (da gennaio 2021) e comunità, letti dal rapporto mensile dell’INFOVI del MAPA. Perimetro più stretto di quello di campagna (operatori che dichiarano ogni mese), quindi non si mescolano. Il mese si legge dal titolo di ogni cartella, perché i nomi dei file non sono fissi. Un mese senza cartella è un vuoto; una tabella assente, nessun dato (mai zero). Le differenze dello 0,2–1 % tra la chiusura di un mese e l’apertura del successivo sono revisioni del MAPA e vengono segnalate. Riutilizzo con citazione della fonte. Settimanale (giovedì).' },
          { b: 'Spagna — MAPA (bilancio del vino, storico).', t: 'Bilancio ufficiale del vino delle campagne 2009/10-2015/16 in migliaia di hl: scorte, produzione, importazioni, esportazioni, utilizzo interno e scorte finali, nazionale, dai file del MAPA. Le celle vuote sono vuoti, mai zero; il definitivo sostituisce il provvisorio (il 2015/16 è provvisorio). Nessuna ripartizione per regione né bilancio dal 2016/17 al 2019/20, e non è confrontabile con le dichiarazioni INFOVI.' },
          { b: 'Energia e fertilizzanti.', t: 'Gasolio USA (EIA, settimanale) e UE (Oil Bulletin, settimanale); gas naturale (EIA settimanale; Banca mondiale mensile), petrolio WTI e Brent (EIA, settimanale); urea (Banca mondiale, mensile).' },
          { b: 'Clima — NASA POWER.', t: 'Pioggia e temperatura mensili (rianalisi MERRA-2) in 31 punti rappresentativi di regioni produttrici, confrontate con la media 2001-2020 dello stesso mese, con storico mensile dal 2000. I mesi più recenti sono calcolati dalla NASA con un diverso flusso di elaborazione (GEOS-IT) che potrebbe essere rivisto. È contesto climatico (una cella di circa 50 km, non una stazione né l’intera regione); non prevede raccolti né prezzi.' },
          { b: 'Offerta e domanda — USDA PSD.', t: 'Bilanci per paese e campagna di cereali, semi oleosi, carne, latte e zucchero (licenza CC BY 4.0), mensili con il WASDE.' },
          { b: 'Farina di soia degli Stati Uniti — USDA AMS.', t: 'Prezzo settimanale della farina di soia (Iowa, FOB, 46,5-48 % di proteine) dal rapporto 3511 di USDA AMS Market News, per tonnellata corta. È un mercato regionale, non un future; il confronto con l’Europa è indicativo.' },
          { b: 'Tassi di cambio.', t: 'Tassi di riferimento della Banca centrale europea, ogni giorno lavorativo.' }
        ] },
        { h: 'Date: osservazione e pubblicazione', p: ['Ogni dato ha due date: l’osservazione (il periodo a cui si riferisce) e la pubblicazione (quando la fonte l’ha diffuso). Alcune fonti non indicano la data di pubblicazione; in tal caso registriamo il giorno in cui abbiamo raccolto il dato la prima volta e lo annotiamo nella scheda.'] },
        { h: 'Valute e unità', p: ['I dati sono conservati nella valuta e nell’unità della fonte. Per confrontarli, il pannello li converte con il tasso di riferimento della BCE dell’ultimo giorno lavorativo e con fattori di unità fissi e visibili (ad esempio, 1 dozzina di uova = 0,6804 kg). Una conversione non rende comparabile un dato che non lo è.'] },
        { h: 'Tassi di interesse, valute e provenienza', p: ["I tassi ufficiali di Stati Uniti, area euro, Canada e Australia provengono dalle banche centrali: BCE (tasso sui depositi), Bank of Canada (API Valet) e Reserve Bank of Australia (tabella F1.1); quello degli Stati Uniti (federal funds rate) arriva tramite il set WS_CBPOL della Banca dei regolamenti internazionali (BRI), che riporta la serie della Federal Reserve. La conversione in euro usa le medie mensili storiche della BCE (USD, CAD, AUD, GBP e DKK dal 1999): ogni valore è convertito alla media del proprio mese ed è indicato come conversione, mai come dato della fonte."] },
        { h: "Riproducibilità, revisioni e copertura", p: ["Ogni serie riporta la propria provenienza (file, flusso di aggiornamento e ultima esecuzione, visibili nella pagina di stato). I cambi in periodi già pubblicati vengono rilevati e conservati (data/revisions.json); possono essere revisioni della fonte, correzioni o ricostruzioni dello storico, e la fonte non lo conferma e la cronologia git permette di ricostruire cosa mostrava il sito in una data precisa (script reconstruct-indicator). Il Coverage Score di ogni paese misura quali categorie hanno dati, quante sono aggiornate e quanti periodi coprono. Quando la stessa serie arriva da più fonti si mostra quella a priorità più alta (nazionale, poi Eurostat, internazionale, secondaria) e le altre vengono registrate, senza duplicati."] },
        { h: 'Stato delle colture', id: 'cultivos', p: ['Proviene dal rapporto settimanale Crop Progress dell’USDA NASS (API Quick Stats), pubblicato il lunedì pomeriggio, ora USA, circa da aprile a novembre (il grano invernale è valutato anche in autunno). La valutazione è la quota di superficie in ogni categoria — molto scarso, scarso, discreto, buono, eccellente —; “buono + eccellente” è la somma delle ultime due. È data da corrispondenti locali del NASS, quindi è soggettiva e non è una previsione di raccolto né di prezzi. L’avanzamento è la quota di superficie che ha raggiunto ogni fase (seminato, raccolto...). La media 5 anni e il confronto con l’anno scorso sono un calcolo proprio di Dehesa Index: si prende la stessa data nelle campagne precedenti, con interpolazione tra i rapporti settimanali, e solo se almeno 4 delle 5 campagne hanno dati. Una fase completata (100 %) resta al 100 % nelle settimane successive. I valori che il NASS non pubblica non vengono riempiti.'] },
        { h: 'Mercati USDA', id: 'mercados', p: ['Prezzi di mercato USA come pubblicati da USDA AMS Market News (API MARS): mangimi e sottoprodotti, etanolo e coprodotti, cereali, semi oleosi, legumi, riso, pollame, uova, carne e sottoprodotti, suinetti, bestiame in vendita diretta, fieno e latticini. Vengono letti ogni giorno feriale (alcuni rapporti sono settimanali). Ogni serie è una combinazione fissa di prodotto, qualità, luogo e unità del rapporto stesso; se in uno stesso giorno o settimana ci sono due cifre diverse per la stessa serie, quel punto viene scartato invece di essere indovinato. Valute e unità non vengono convertite. Quando un rapporto indica un prezzo medio viene mostrato quello; quando indica solo minimo e massimo viene mostrato il punto medio, segnalato con ≈. I dati sono ufficiali ma non sono un indicatore di Dehesa Index e non sono confrontabili con quelli europei: ogni rapporto ha la propria base di luogo, qualità e consegna.'] },
        { h: 'Prezzi locali dei cereali (USA)', id: 'precios-locales', p: ['Le offerte d’acquisto in contanti (cash bids) provengono dai rapporti sui cereali di USDA AMS Market News (API MARS), letti in CI; la chiave API non raggiunge mai il browser. Ogni prezzo indica che cosa rappresenta: una regione dello stato, un terminale, un mercato di esportazione o l’intero stato. Dehesa Index non presenta un dato come «elevatore locale» salvo che il rapporto identifichi l’elevatore, e non mette punti sulla mappa senza una posizione reale. Ogni serie è una combinazione fissa di prodotto, classe di frumento, qualità, tipo di acquirente, periodo di consegna e unità; HRW, SRW, HRS e duro non si mescolano mai. Si mostra la media quando il rapporto la dà, il prezzo esatto se minimo e massimo coincidono, altrimenti l’intervallo; mai un punto medio calcolato. La base compare solo se USDA la pubblica e non viene mai calcolata. La variazione è calcolata solo tra osservazioni consecutive vicine (7 giorni per i rapporti giornalieri, 14 per i settimanali). Se USDA corregge un prezzo già pubblicato, si conservano il valore precedente, il nuovo e la data di rilevazione. Se l’API fallisce, si mantiene l’ultimo dato valido e si segnala la freschezza. Non si calcola un premio/sconto rispetto al riferimento nazionale perché il riferimento USA di Dehesa è mensile (NASS) e non è confrontabile con offerte giornaliere. «Vicino a me»: il CAP viene convertito in stato con una tabella locale (ZCTA del censimento 2000, solo stato); è elaborato nel browser e non viene salvato né inviato. Premio biologico (schede mais, soia e grano): mediana delle offerte biologiche USDA AMS 3802 meno mediana delle offerte convenzionali con la stessa specifica (prodotto, classe, grado, elevatore e tipo di offerta) nella stessa data; solo con almeno 3 serie biologiche e 5 convenzionali. Indicativo: due rapporti diversi con copertura regionale e mese di consegna possibilmente diversi.'] },
        { h: 'Esportazioni USA', id: 'exportaciones', p: ['Le vendite all’esportazione settimanali provengono dall’Export Sales Reporting dell’USDA FAS (API aperta della FAS), pubblicato il giovedì, che copre grano, mais, sorgo, orzo, soia e derivati, cotone, riso, manzo e maiale. Le cifre sono tonnellate metriche (cotone in balle) dichiarate dalle imprese all’USDA: «esportato» sono le spedizioni cumulate della campagna, «vendite in sospeso» quelle concluse e non ancora spedite, «impegno totale» la loro somma. I totali sommano le destinazioni pubblicate e l’aggregato UE conta come un’unica destinazione. Il commercio mensile per paese proviene dall’USDA FAS GATS, con dati del Census Bureau: solo il commercio degli Stati Uniti con ciascun paese (non i flussi tra paesi terzi), in dollari correnti e, dove il Census misura in chilogrammi, in tonnellate; sono inclusi i principali partner agricoli, non tutti i paesi. I gruppi di prodotto si basano sui capitoli tariffari (SA) e sono approssimativi. Gli ultimi due mesi possono essere rivisti. Dati pubblici del governo USA; non convertiti né confrontati con i prezzi.'] },
        { h: 'Scheda prodotto', id: 'producto', p: ['La scheda prodotto (grano, mais, soia, riso, bovino, suino, latte e pollo) non crea dati nuovi: riunisce in una pagina ciò che ogni blocco già pubblica, con la sua fonte e unità (prezzi, offerta e domanda, vendite all’esportazione, commercio per paese, coltura o consistenza del bestiame, siccità e costi). I mercati non vengono convertiti né sommati: il prezzo USA di bovino e suino è a peso vivo e non equivale al prezzo in carcassa europeo. La media della siccità ponderata per la produzione è un calcolo di Dehesa sui 5 maggiori Stati produttori ed esprime la quota della superficie dello Stato in siccità moderata o peggiore, non della superficie coltivata. Un blocco senza dati non compare. Per la soia, il prezzo mostrato è quello della farina, non dei semi.'] },
        { h: 'Prezzi UE', id: 'europa', p: ['La pagina Prezzi UE riunisce tutte le serie di prezzi pubblicate dalla Commissione europea nel suo Agri-food Data Portal (API pubblica): cereali, semi oleosi e farine, latticini, bovini, suino, pollo, uova, agnello, riso, latte crudo, olio d’oliva, zucchero, vino e fertilizzanti, paese per paese. Ogni linea è il prezzo pubblicato dal portale, nella sua unità (€/t, €/100 kg, €/hl…), senza conversioni né medie tra mercati; se un paese pubblica più mercati, ciascuno è mostrato separatamente e le righe non in euro vengono scartate. «UE» è un aggregato calcolato dalla Commissione, non da Dehesa Index. Il portale non pubblica la data di rilascio di ogni dato né tutti i paesi ogni settimana, quindi alcuni paesi hanno lacune. Si aggiorna il giovedì; lo storico arriva al 2015 per la maggior parte delle famiglie (2021 per cereali e bovini) e, per zucchero, vino e fertilizzanti, fin dove lo pubblica la fonte.'] },
        { h: 'Monitor della siccità USA', id: 'sequia', p: ['La quota di ogni Stato in siccità proviene dall’U.S. Drought Monitor, elaborato dal National Drought Mitigation Center (Università del Nebraska-Lincoln) con USDA e NOAA. Viene pubblicato il giovedì con la mappa valida il martedì precedente. Le categorie D0–D4 sono mostrate come pubblicate dall’API (cumulative: D1 include D2, D3 e D4); le variazioni sono calcolate sottraendo le percentuali (punti percentuali) rispetto alla settimana precedente e a 52 settimane prima. È una valutazione, non una previsione.'] },
        { h: 'Zootecnia e latte negli USA', id: 'ganaderia', p: ['Gli inventari di suini e bovini, la produzione di latte per Stato e le scorte in frigo provengono dall’USDA NASS (Quick Stats: Hogs and Pigs, Cattle, Milk Production e Cold Storage) e sono mostrati come pubblicati, nella loro unità originale. Le indagini sui suini sono trimestrali, quelle sui bovini semestrali, latte e scorte in frigo mensili. I dati per Stato sono mostrati solo se NASS li pubblica per lo stesso periodo. Le variazioni sono semplici variazioni percentuali tra due dati pubblicati.'] },
        { h: 'Costi degli input agricoli negli USA', id: 'insumos', p: ['Gli indici dei prezzi pagati dagli agricoltori (fertilizzanti, carburanti, mangimi, agrochimici, sementi, macchinari, servizi, salari, affitti e interessi) provengono dall’USDA NASS, Agricultural Prices (Quick Stats), base 2011 = 100. NASS non pubblica più prezzi assoluti di fertilizzanti né carburanti, quindi si mostrano gli indici ufficiali, senza stimare prezzi per tonnellata o per litro. Le variazioni sono variazioni percentuali tra indici pubblicati.'] },
        { h: 'Prezzi alimentari, costi e reddito agricolo USA', id: 'costes', p: ['I prezzi alimentari (previsioni IPC e IPP), i costi e ricavi per coltura e allevamento, le previsioni dei costi e il reddito agricolo provengono dai file ufficiali dell’USDA Economic Research Service (Food Price Outlook, Commodity Costs and Returns, Cost of Production Forecasts e Farm Income and Wealth Statistics). Sono mostrati come pubblicati; l’ultimo anno di reddito agricolo e le previsioni di prezzi e costi sono previsioni dell’ERS. Il punto di pareggio per unità è calcolato da Dehesa (costo totale per acro diviso per la resa per acro) ed è indicato come tale nella pagina.'] },
        { h: 'Rese e superfici per Stato USA', id: 'rendimientos', p: ['La resa per acro, le superfici seminate e raccolte e la produzione per Stato provengono dall’USDA NASS (Quick Stats, indagini Crop Production e Acreage), nelle unità originali (acri, bushel, libbre). I dati per contea (stime di contea del NASS via Quick Stats, aggiornate ogni mese) esistono solo per le colture e le contee che il NASS pubblica; la copertura cambia ogni anno e le contee senza dato sono in grigio, mai a zero. «Altre contee» è la somma che il NASS non dettaglia. I confini provengono dal Census Bureau (dominio pubblico, via us-atlas). L’ultimo anno può essere una stima o previsione NASS finché la campagna non è chiusa; gli Stati senza dato pubblicato non vengono completati.'] },
        { h: 'Manitoba: bovini, ovini, caprini e suini', id: 'manitoba', p: ['I prezzi delle aste di bovini, ovini e caprini e quelli dei suini dei trasformatori del Manitoba provengono dai rapporti settimanali (PDF) di Manitoba Agriculture, con licenza OpenMB (attribuzione obbligatoria). Ogni rapporto è letto da un lettore che rifiuta di pubblicare ciò che non torna: capi che non sommano, minimo, media e massimo in disordine, date impossibili, prezzi fuori intervallo. Il Manitoba pubblicava le capre a capo e da aprile 2025 le converte in C$/cwt con pesi medi che stima da sé; sono accettate solo se il rapporto lo indica. Se due rapporti danno cifre diverse per la stessa vendita, la cella resta vuota (un vuoto, mai uno zero). Le variazioni confrontano sempre la stessa serie con le sue date; lo storico mensile di Canfax non è usato.'] },
        { h: 'Offerta e domanda', id: 'oferta-demanda', p: ['I bilanci di produzione, consumo, commercio e scorte provengono dall’USDA Foreign Agricultural Service (PSD Online, licenza CC BY 4.0) e sono aggiornati con il rapporto mensile WASDE. La campagna indicata (2025) è quella che inizia quell’anno (2025/26); la più recente è una previsione che l’USDA rivede ogni mese. “Mondo” è la somma dei paesi della base PSD, con la UE contata una volta; non è una cifra pubblicata dall’USDA. Le campagne differiscono tra paesi, ed esportazioni e importazioni sono dichiarate separatamente: il commercio mondiale non sempre quadra. Cifre in migliaia di tonnellate (carne in equivalente carcassa). Senza dati PSD, non si disegna nulla.'] },
        { h: 'Dehesa Index: l’indice composito', id: 'indice', p: ['Un indice mensile con base 100 a ottobre 2024, per il mercato UE (con i pesi sotto). Gli Stati Uniti hanno un proprio indice, con stessa base e metodo, costruito con USDA NASS, USDA AMS ed EIA; senza gruppo fertilizzanti (nessuna serie verificata) e con gli altri pesi riscalati; WTI al posto del Brent e niente agnello. Anche il Canada ha il suo, con i prezzi alla produzione di Statistics Canada in dollari canadesi; senza gruppi mangimi, fertilizzanti ed energia (nessuna serie verificata con storia sufficiente), con gli altri pesi riscalati e con ultimo mese quello per cui tutte le serie hanno dati, perché Statistics Canada pubblica con circa due mesi di ritardo. Ogni serie verificata viene convertita in media mensile e ribasata a 100; ogni gruppo è la media semplice delle sue serie; l’indice è la media ponderata dei gruppi: Cereali 25 %, Zootecnia 25 %, Latticini 15 %, Mangimi 15 %, Fertilizzanti 10 %, Energia 10 %.', 'Poiché ogni serie è ribasata nella propria unità, l’indice misura un andamento, non è un prezzo e non mescola le valute. Se una serie ha un mese mancante alla fonte, si riporta il mese precedente e lo si dichiara nel file dei dati. Il Regno Unito verrà aggiunto quando avrà almeno 24 mesi di storico. Il pannello «Crea il tuo indice» permette di cambiare i pesi e confrontarli con l’indice ufficiale.'] },
        { h: 'Limiti', ul: [
          { t: 'Non sono prezzi in tempo reale: la frequenza dipende da ciascuna fonte (settimanale, mensile o trimestrale).' },
          { t: 'I prezzi USA (NASS) sono alla produzione e quelli UE sono prezzi di mercato; anche se mostrati nella stessa valuta, non sono sempre lo stesso concetto.' },
          { t: 'Le fonti possono rivedere i dati o cambiare le definizioni; mostriamo l’ultima versione pubblicata.' },
          { t: 'Nulla qui costituisce consulenza finanziaria o di investimento.' }
        ] },
        { h: 'Dati aperti e correzioni', p: ['I file con cui è costruito il pannello sono pubblicati nella cartella dei dati del sito (JSON e CSV), con la fonte e la metodologia di ogni serie. Se noti un errore o una definizione migliorabile, scrivi a hola@dehesaindex.com.'] }
      ],
      links: [{ href: 'clima.html', t: 'Clima agricolo' }, { href: 'data/', t: 'Dati aperti' }, { href: 'legal.html', t: 'Note legali e privacy' }, { href: 'informacion.html', t: 'Informazioni' }]
    }
  };
  window.DehesaTextPage(STRINGS, 'informacion');
})();
